/* ---------- storage: Claude artifact storage, else localStorage ---------- */
const store = {
  async get(key) {
    if (window.storage && window.storage.get) {
      const res = await window.storage.get(key);
      return res && res.value != null ? res.value : null;
    }
    return window.localStorage ? window.localStorage.getItem(key) : null;
  },
  async set(key, value) {
    if (window.storage && window.storage.set) return window.storage.set(key, value);
    if (window.localStorage) window.localStorage.setItem(key, value);
  },
};

/* re-render on an interval so clocks / "x ago" labels stay current */
function useTick(ms) {
  const [, setT] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setT((t) => t + 1), ms);
    return () => clearInterval(id);
  }, [ms]);
}

