/* =========================================================
   Resistor Color Code — data + helpers (ported from ResistorColorCode.jsx)
   ========================================================= */
const fmtR = (n) => {
  if (!isFinite(n)) return "—";
  let val = n, unit = "";
  if (Math.abs(n) >= 1e6) { val = n / 1e6; unit = "M"; }
  else if (Math.abs(n) >= 1e3) { val = n / 1e3; unit = "k"; }
  return parseFloat(val.toFixed(4)).toString() + unit;
};

const RCC_DIGITS = ["Black", "Brown", "Red", "Orange", "Yellow", "Green", "Blue", "Violet", "Grey", "White"];
const RCC_MULT = [
  { name: "Black", value: 1 }, { name: "Brown", value: 10 }, { name: "Red", value: 100 },
  { name: "Orange", value: 1000 }, { name: "Yellow", value: 10000 }, { name: "Green", value: 100000 },
  { name: "Blue", value: 1000000 }, { name: "Violet", value: 10000000 },
  { name: "Gold", value: 0.1 }, { name: "Silver", value: 0.01 },
];
const RCC_TOL = [
  { name: "Brown", value: 1 }, { name: "Red", value: 2 }, { name: "Green", value: 0.5 },
  { name: "Blue", value: 0.25 }, { name: "Violet", value: 0.1 }, { name: "Grey", value: 0.05 },
  { name: "Gold", value: 5 }, { name: "Silver", value: 10 },
];
const RCC_TEMPCO = [
  { name: "Black", value: 250 }, { name: "Brown", value: 100 }, { name: "Red", value: 50 },
  { name: "Orange", value: 15 }, { name: "Yellow", value: 25 }, { name: "Green", value: 20 },
  { name: "Blue", value: 10 }, { name: "Violet", value: 5 }, { name: "Grey", value: 1 },
];
const RCC_HEX = {
  Black: "#232323", Brown: "#8a5a35", Red: "#d0342c", Orange: "#f0942a", Yellow: "#f2d24e",
  Green: "#3a8f5c", Blue: "#3273b0", Violet: "#7d4ba0", Grey: "#9b9b9b", White: "#f6f6f2",
  Gold: "#c9a233", Silver: "#c7c7c7",
};
const RCC_LIGHT = ["White", "Silver", "Yellow", "Grey"];

const RCC_DEFAULT_DIGITS = [1, 0, 0];
const RCC_DEFAULT_MULT = 1000;
const RCC_DEFAULT_TOL = 5;
const RCC_DEFAULT_TEMPCO = 100;

function rccSlotDefs(count) {
  const digitCount = count >= 5 ? 3 : 2;
  const slots = [];
  for (let i = 0; i < digitCount; i++) slots.push({ type: "digit", label: `${i === 0 ? "1st" : i === 1 ? "2nd" : "3rd"} Band (Digit)` });
  slots.push({ type: "mult", label: `${digitCount + 1 === 2 ? "2nd" : digitCount + 1 === 3 ? "3rd" : digitCount + 1 === 4 ? "4th" : "5th"} Band (Mult.)` });
  if (count >= 4) slots.push({ type: "tol", label: `${digitCount + 2}${digitCount + 2 === 2 ? "nd" : "th"} Band (Tol.)` });
  if (count >= 6) slots.push({ type: "tempco", label: `${digitCount + 3}th Band (Temp. Co.)` });
  return slots;
}

function rccOptionsFor(type) {
  if (type === "digit") return RCC_DIGITS.map((name, v) => ({ value: v, color: name, text: `${name} (${v})` }));
  if (type === "mult") return RCC_MULT.map((m) => ({ value: m.value, color: m.name, text: `${m.name} (×${fmtR(m.value)}Ω)` }));
  if (type === "tol") return RCC_TOL.map((t) => ({ value: t.value, color: t.name, text: `${t.name} (±${t.value}%)` }));
  return RCC_TEMPCO.map((t) => ({ value: t.value, color: t.name, text: `${t.name} (${t.value}ppm/K)` }));
}

function rccDefaultFor(type, digitIdx) {
  if (type === "digit") return RCC_DEFAULT_DIGITS[digitIdx];
  if (type === "mult") return RCC_DEFAULT_MULT;
  if (type === "tol") return RCC_DEFAULT_TOL;
  return RCC_DEFAULT_TEMPCO;
}

function rccNearestBands(target, digitCount) {
  let best = null;
  const range = digitCount === 3 ? 1000 : 100;
  for (let n = 0; n < range; n++) {
    const digits = digitCount === 3
      ? [Math.floor(n / 100), Math.floor(n / 10) % 10, n % 10]
      : [Math.floor(n / 10), n % 10];
    for (const m of RCC_MULT) {
      const val = n * m.value;
      const err = Math.abs(val - target);
      if (!best || err < best.err) best = { digits, mult: m, value: val, err };
    }
  }
  return best;
}

