/* =========================================================
   Ohm's Law screen
   ========================================================= */
const ohmFmt = (n) => {
  if (n === undefined || !isFinite(n)) return "—";
  const abs = Math.abs(n);
  if (abs !== 0 && (abs < 0.001 || abs >= 100000)) return n.toExponential(3);
  return parseFloat(n.toFixed(4)).toString();
};

const OHM_PRESETS = [
  { label: "12V, 4Ω", v: "12", i: "", r: "4", p: "" },
  { label: "9V, 0.5A", v: "9", i: "0.5", r: "", p: "" },
  { label: "2A, 24W", v: "", i: "2", r: "", p: "24" },
  { label: "100Ω, 0.9W", v: "", i: "", r: "100", p: "0.9" },
];

function OhmScreen({ onBack }) {
  const [raw, setRaw] = useState({ v: "12", i: "", r: "4", p: "" });
  const [result, setResult] = useState(null);
  const [error, setError] = useState("");

  const set = (k) => (e) => setRaw((s) => ({ ...s, [k]: e.target.value }));

  const solve = (input = raw) => {
    const given = {};
    Object.entries(input).forEach(([k, val]) => {
      if (val !== "" && !isNaN(parseFloat(val))) given[k.toUpperCase()] = parseFloat(val);
    });
    const filled = Object.keys(given);

    if (filled.length < 2) {
      setError("Enter at least two values.");
      setResult(null);
      return;
    }
    setError("");

    const order = ["V", "I", "R", "P"];
    const pair = order.filter((k) => filled.includes(k)).slice(0, 2);
    const pairSet = pair.slice().sort().join("");
    const gv = given;
    let V, I, R, P;
    const steps = [];

    if (pairSet === "IV") {
      V = gv.V; I = gv.I;
      R = V / I; steps.push(`R = V / I = ${V} / ${I} = ${ohmFmt(R)} Ω`);
      P = V * I; steps.push(`P = V × I = ${V} × ${I} = ${ohmFmt(P)} W`);
    } else if (pairSet === "RV") {
      V = gv.V; R = gv.R;
      I = V / R; steps.push(`I = V / R = ${V} / ${R} = ${ohmFmt(I)} A`);
      P = (V * V) / R; steps.push(`P = V² / R = ${V}² / ${R} = ${ohmFmt(P)} W`);
    } else if (pairSet === "PV") {
      V = gv.V; P = gv.P;
      I = P / V; steps.push(`I = P / V = ${P} / ${V} = ${ohmFmt(I)} A`);
      R = (V * V) / P; steps.push(`R = V² / P = ${V}² / ${P} = ${ohmFmt(R)} Ω`);
    } else if (pairSet === "IR") {
      I = gv.I; R = gv.R;
      V = I * R; steps.push(`V = I × R = ${I} × ${R} = ${ohmFmt(V)} V`);
      P = I * I * R; steps.push(`P = I² × R = ${I}² × ${R} = ${ohmFmt(P)} W`);
    } else if (pairSet === "IP") {
      I = gv.I; P = gv.P;
      V = P / I; steps.push(`V = P / I = ${P} / ${I} = ${ohmFmt(V)} V`);
      R = P / (I * I); steps.push(`R = P / I² = ${P} / ${I}² = ${ohmFmt(R)} Ω`);
    } else if (pairSet === "PR") {
      R = gv.R; P = gv.P;
      V = Math.sqrt(P * R); steps.push(`V = √(P × R) = √(${P} × ${R}) = ${ohmFmt(V)} V`);
      I = Math.sqrt(P / R); steps.push(`I = √(P / R) = √(${P} / ${R}) = ${ohmFmt(I)} A`);
    }

    const computed = { V, I, R, P };
    const mismatches = [];
    filled.forEach((k) => {
      if (!pair.includes(k)) {
        const provided = given[k], calc = computed[k];
        const relErr = Math.abs(provided - calc) / Math.max(Math.abs(calc), 1e-9);
        if (relErr > 0.01) mismatches.push({ k, provided, calc });
      }
    });

    setResult({ vals: computed, pair, steps, mismatches });
  };

  const applyPreset = (p) => {
    const next = { v: p.v, i: p.i, r: p.r, p: p.p };
    setRaw(next);
    solve(next);
  };

  const onKeyDown = (e) => { if (e.key === "Enter") solve(); };

  const ohmUnits = { V: "V", I: "A", R: "Ω", P: "W" };
  const ohmOrder = ["V", "I", "R", "P"];
  const ohmFields = [
    { key: "v", label: "Voltage", ph: "V" },
    { key: "i", label: "Current", ph: "A" },
    { key: "r", label: "Resistance", ph: "Ω" },
    { key: "p", label: "Power", ph: "W" },
  ];

  // same dark "instrument module" palette used for Resistor Code
  // accent follows the module's home-card color
  const oBg = "#181512", oPanel = "#211c17", oGold = "#FF9736", oGoldBright = "#ffc690";
  const oTeal = "#ffb168", oCream = "#f4efe4", oMuted = "#a89f8f", oLine = "#3a3327", oDanger = "#e8735a";

  return (
    <div className="screen-body">
      <div className="header">
        <div className="back neu" onClick={onBack} style={{ cursor: "pointer" }}>
          <BackIcon />
        </div>
        <div className="hlabel">MODULE &middot; OHM'S LAW</div>
      </div>

      <div style={{ margin: "14px 22px 0 22px", background: oPanel, color: oCream, fontFamily: "Inter, Arial, sans-serif", borderRadius: 20, padding: 18 }}>
        <p style={{ fontFamily: "monospace", fontSize: 10, letterSpacing: "0.14em", textTransform: "uppercase", color: oTeal, margin: "0 0 6px" }}>MOD.01</p>
        <h2 style={{ fontWeight: 800, fontSize: 20, margin: "0 0 4px", fontFamily: "'Baloo 2',sans-serif" }}>
          Ohm's <span style={{ color: oGoldBright }}>Law</span> Solver
        </h2>
        <p style={{ color: oMuted, fontSize: 11.5, margin: "0 0 16px", lineHeight: 1.4 }}>Enter any two values.</p>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
          {ohmFields.map((f) => (
            <div key={f.key}>
              <label style={{ display: "block", fontSize: 9.5, color: oMuted, marginBottom: 4, textTransform: "uppercase", letterSpacing: "0.05em" }}>{f.label}</label>
              <input
                type="number"
                step="any"
                placeholder={f.ph}
                value={raw[f.key]}
                onChange={set(f.key)}
                onKeyDown={onKeyDown}
                style={{
                  width: "100%", background: oBg, border: `1px solid ${oGold}4d`, color: oCream,
                  fontFamily: "monospace", fontSize: 13, padding: "8px 9px", borderRadius: 8, outline: "none", boxSizing: "border-box",
                }}
              />
            </div>
          ))}
        </div>
        <button
          onClick={() => solve()}
          style={{ marginTop: 12, width: "100%", background: oGold, color: "#181512", fontWeight: 700, fontSize: 13, letterSpacing: "0.03em", padding: "11px 20px", borderRadius: 8, border: "none", cursor: "pointer" }}
        >
          Solve →
        </button>
        {error && <div style={{ marginTop: 8, color: oDanger, fontSize: 12 }}>{error}</div>}

        <p style={{ fontSize: 10.5, color: oMuted, margin: "16px 0 6px" }}>Quick examples</p>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 6 }}>
          {OHM_PRESETS.map((p) => (
            <button
              key={p.label}
              onClick={() => applyPreset(p)}
              style={{ fontFamily: "monospace", fontSize: 11, background: oBg, border: `1px solid ${oGold}40`, color: oCream, borderRadius: 7, padding: "7px 8px", cursor: "pointer" }}
            >
              {p.label}
            </button>
          ))}
        </div>
      </div>

      <div style={{ margin: "14px 22px 0 22px", background: oPanel, color: oCream, borderRadius: 20, padding: 18 }}>
        <p style={{ fontFamily: "monospace", fontSize: 10, color: oMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 10px" }}>Solved</p>
        {result ? (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 8 }}>
            {ohmOrder.map((k) => {
              const derived = !result.pair.includes(k);
              return (
                <div key={k} style={{ textAlign: "center" }}>
                  <div style={{ fontFamily: "monospace", fontWeight: 700, fontSize: 13, color: derived ? oTeal : oGoldBright, wordBreak: "break-word" }}>
                    {ohmFmt(result.vals[k])}{ohmUnits[k]}
                  </div>
                  <div style={{ fontFamily: "monospace", fontSize: 8.5, color: oMuted, marginTop: 3, textTransform: "uppercase", letterSpacing: "0.04em" }}>
                    {k} · {derived ? "solved" : "given"}
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div style={{ color: oMuted, fontSize: 12 }}>—</div>
        )}
      </div>

      <div style={{ margin: "14px 22px 0 22px", background: oPanel, color: oCream, borderRadius: 20, padding: 18 }}>
        <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 10px", fontFamily: "'Baloo 2',sans-serif" }}>Steps</h3>
        {result?.steps.length ? (
          result.steps.map((s, idx) => (
            <div key={idx} style={{ fontFamily: "monospace", fontSize: 11.5, padding: "3px 0" }}>{s}</div>
          ))
        ) : (
          <div style={{ color: oMuted, fontSize: 12 }}>—</div>
        )}
      </div>

      {result?.mismatches.length > 0 && (
        <div style={{ margin: "14px 22px 0 22px", background: oPanel, color: oCream, borderRadius: 20, padding: 18 }}>
          <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 10px", fontFamily: "'Baloo 2',sans-serif" }}>Consistency check</h3>
          {result.mismatches.map((m) => (
            <div key={m.k} style={{ color: oDanger, fontSize: 11.5, fontFamily: "monospace" }}>
              {m.k}: entered {ohmFmt(m.provided)}, calculated {ohmFmt(m.calc)}.
            </div>
          ))}
        </div>
      )}

      <div style={{ margin: "14px 22px 26px 22px", background: oPanel, color: oCream, borderRadius: 20, padding: 18 }}>
        <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 10px", fontFamily: "'Baloo 2',sans-serif" }}>Formula reference</h3>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 11.5 }}>
          <tbody>
            {[
              ["V", "IR = P/I = √(PR)"],
              ["I", "V/R = P/V = √(P/R)"],
              ["R", "V/I = V²/P = P/I²"],
              ["P", "VI = V²/R = I²R"],
            ].map(([name, formula]) => (
              <tr key={name} style={{ borderTop: `1px solid ${oLine}` }}>
                <td style={{ padding: "7px 4px", color: oGold, fontWeight: 700, width: 32 }}>{name}</td>
                <td style={{ padding: "7px 4px", fontFamily: "monospace", color: oMuted }}>{formula}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* =========================================================
   Boolean Algebra & K-Map — shared logic (ported from BooleanKMap.jsx)
   ========================================================= */
const BK_PREC = { NOT_PRE: 4, AND: 3, XOR: 2, OR: 1 };

function bkTokenize(raw) {
  const tokens = [];
  const s = raw.replace(/\s+/g, "");
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if ("ABCD".includes(c)) tokens.push({ type: "VAR", value: c });
    else if (c === "0" || c === "1") tokens.push({ type: "CONST", value: c === "1" ? 1 : 0 });
    else if (c === "(") tokens.push({ type: "LP" });
    else if (c === ")") tokens.push({ type: "RP" });
    else if (c === "!" || c === "~" || c === "¬") tokens.push({ type: "NOT_PRE" });
    else if (c === "'") tokens.push({ type: "NOT_POST" });
    else if (c === "*" || c === "." || c === "·" || c === "∧") tokens.push({ type: "AND" });
    else if (c === "+" || c === "∨") tokens.push({ type: "OR" });
    else if (c === "^" || c === "⊕") tokens.push({ type: "XOR" });
    else throw new Error(`Unrecognized symbol "${c}". Use A–D, 0, 1, ¬ ∧ ∨ ⊕, or ( ).`);
  }
  return tokens;
}

function bkWithImplicitAnd(tokens) {
  const out = [];
  const endsValue = (t) => t && (t.type === "VAR" || t.type === "CONST" || t.type === "RP" || t.type === "NOT_POST");
  const startsValue = (t) => t && (t.type === "VAR" || t.type === "CONST" || t.type === "LP" || t.type === "NOT_PRE");
  for (let i = 0; i < tokens.length; i++) {
    if (i > 0 && endsValue(tokens[i - 1]) && startsValue(tokens[i])) out.push({ type: "AND" });
    out.push(tokens[i]);
  }
  return out;
}

function bkToRPN(tokens) {
  const output = [];
  const ops = [];
  const isBin = (t) => t.type === "AND" || t.type === "OR" || t.type === "XOR";
  const normalize = (t) => (t.type === "NOT_PRE" ? { type: "NOT" } : t);
  const popToOutput = () => output.push(normalize(ops.pop()));
  for (const tok of tokens) {
    if (tok.type === "VAR" || tok.type === "CONST") output.push(tok);
    else if (tok.type === "NOT_POST") output.push({ type: "NOT" });
    else if (tok.type === "NOT_PRE") ops.push(tok);
    else if (isBin(tok)) {
      while (ops.length) {
        const top = ops[ops.length - 1];
        if (top.type === "LP") break;
        const pTop = BK_PREC[top.type], pCur = BK_PREC[tok.type];
        if (pTop > pCur || pTop === pCur) popToOutput();
        else break;
      }
      ops.push(tok);
    } else if (tok.type === "LP") ops.push(tok);
    else if (tok.type === "RP") {
      while (ops.length && ops[ops.length - 1].type !== "LP") popToOutput();
      if (!ops.length) throw new Error("Mismatched parentheses.");
      ops.pop();
      while (ops.length && ops[ops.length - 1].type === "NOT_PRE") popToOutput();
    }
  }
  while (ops.length) {
    if (ops[ops.length - 1].type === "LP") throw new Error("Mismatched parentheses.");
    popToOutput();
  }
  return output;
}

function bkEvalRPN(rpn, env) {
  const st = [];
  for (const tok of rpn) {
    if (tok.type === "VAR") st.push(env[tok.value]);
    else if (tok.type === "CONST") st.push(tok.value);
    else if (tok.type === "NOT") st.push(st.pop() ? 0 : 1);
    else {
      const b = st.pop(), a = st.pop();
      if (tok.type === "AND") st.push(a & b);
      else if (tok.type === "OR") st.push(a | b);
      else if (tok.type === "XOR") st.push(a ^ b);
    }
  }
  if (st.length !== 1) throw new Error("Incomplete expression.");
  return st[0];
}

function bkGetVariables(tokens) {
  const set = new Set();
  tokens.forEach((t) => { if (t.type === "VAR") set.add(t.value); });
  return ["A", "B", "C", "D"].filter((v) => set.has(v));
}

/* Quine–McCluskey */
function bkToBin(num, n) { return num.toString(2).padStart(n, "0"); }

function bkDiffOne(a, b) {
  let count = 0, pos = -1, combined = "";
  for (let k = 0; k < a.length; k++) {
    if (a[k] !== b[k]) {
      if (a[k] === "-" || b[k] === "-") return { count: 2 };
      count++; pos = k; combined += "-";
    } else combined += a[k];
  }
  return { count, pos, combined };
}

function bkRunQM(minterms, n, vars, log, dontCares = []) {
  if (minterms.length === 0) return { selected: [], allZero: true, primes: [], essential: [], additional: null };
  if (minterms.length + dontCares.length === Math.pow(2, n)) {
    const pi = { bits: "-".repeat(n), minterms: [...minterms, ...dontCares].sort((a, b) => a - b) };
    return { selected: [pi], allOne: true, primes: [pi], essential: [], additional: null };
  }

  // don't-cares join the grouping (so groups can grow) but never need covering
  const seed = [...new Set([...minterms, ...dontCares])].sort((a, b) => a - b);
  let current = seed.map((m) => ({ bits: bkToBin(m, n), minterms: [m] }));
  const allPrimes = [];
  let round = 1;
  while (current.length) {
    const used = new Set();
    const nextMap = new Map();
    for (let i = 0; i < current.length; i++) {
      for (let j = i + 1; j < current.length; j++) {
        const d = bkDiffOne(current[i].bits, current[j].bits);
        if (d.count === 1) {
          used.add(i); used.add(j);
          const combinedMinterms = [...new Set([...current[i].minterms, ...current[j].minterms])].sort((a, b) => a - b);
          const key = d.combined + "|" + combinedMinterms.join(",");
          if (!nextMap.has(key)) nextMap.set(key, { bits: d.combined, minterms: combinedMinterms });
          log.push({
            round,
            aMinterms: current[i].minterms, aBits: current[i].bits,
            bMinterms: current[j].minterms, bBits: current[j].bits,
            resultBits: d.combined, eliminatedVar: vars[d.pos],
          });
        }
      }
    }
    current.forEach((t, idx) => { if (!used.has(idx)) allPrimes.push(t); });
    if (nextMap.size === 0) break;
    current = [...nextMap.values()];
    round++;
  }
  const primeMap = new Map();
  allPrimes.forEach((p) => primeMap.set(p.bits + "#" + p.minterms.join(","), p));
  // a group made only of don't-cares is never useful
  const primes = [...primeMap.values()].filter((p) => p.minterms.some((m) => minterms.includes(m)));

  const selected = [];
  const essential = []; // { minterm, prime }
  const uncovered = new Set(minterms);
  minterms.forEach((m) => {
    const covering = primes.filter((p) => p.minterms.includes(m));
    if (covering.length === 1) {
      essential.push({ minterm: m, prime: covering[0] });
      if (!selected.includes(covering[0])) selected.push(covering[0]);
    }
  });
  selected.forEach((pi) => pi.minterms.forEach((m) => uncovered.delete(m)));

  let additional = null;
  if (uncovered.size > 0) {
    const remaining = primes.filter((p) => !selected.includes(p));
    const uncoveredArr = [...uncovered];
    let bestCombo = null;
    const combos = (arr, size) => {
      const results = [];
      const rec = (start, combo) => {
        if (combo.length === size) { results.push(combo.slice()); return; }
        for (let i = start; i < arr.length; i++) { combo.push(arr[i]); rec(i + 1, combo); combo.pop(); }
      };
      rec(0, []);
      return results;
    };
    for (let size = 1; size <= remaining.length && !bestCombo; size++) {
      for (const combo of combos(remaining, size)) {
        const covered = new Set();
        combo.forEach((pi) => pi.minterms.forEach((m) => covered.add(m)));
        if (uncoveredArr.every((m) => covered.has(m))) { bestCombo = combo; break; }
      }
    }
    if (bestCombo) {
      additional = { uncovered: uncoveredArr, added: bestCombo };
      selected.push(...bestCombo);
    }
  }
  return { selected, primes, essential, additional };
}

function bkBitsToExpr(bits, vars) {
  let term = "";
  for (let i = 0; i < bits.length; i++) {
    if (bits[i] === "1") term += vars[i];
    else if (bits[i] === "0") term += vars[i] + "'";
  }
  return term;
}

/* K-map layout */
const BK_GRAY2 = ["0", "1"];
const BK_GRAY4 = ["00", "01", "11", "10"];
const BK_PI_COLORS = ["#49d6c4", "#e3b23c", "#e8735a", "#9b8cf0", "#6fd1ff", "#f2a9c9"];

function bkKmapLayout(n) {
  if (n === 1) return { rows: [""], cols: BK_GRAY2, rowBits: 0, colBits: 1 };
  if (n === 2) return { rows: BK_GRAY2, cols: BK_GRAY2, rowBits: 1, colBits: 1 };
  if (n === 3) return { rows: BK_GRAY2, cols: BK_GRAY4, rowBits: 1, colBits: 2 };
  if (n === 4) return { rows: BK_GRAY4, cols: BK_GRAY4, rowBits: 2, colBits: 2 };
  return null;
}

const BK_PRESETS = {
  custom: { label: "Custom", expr: null, note: null },
  demorgan: { label: "De Morgan's", expr: "(A+B)'", note: "De Morgan's: (A+B)' = A'·B' — OR becomes AND under negation." },
  absorption: { label: "Absorption", expr: "A + AB", note: "Absorption: A + AB = A — AB adds nothing new." },
  xor: { label: "Exclusive OR", expr: "AB' + A'B", note: "XOR: AB'+A'B — not adjacent on the map, can't reduce further." },
  consensus: { label: "Consensus", expr: "AB + A'C + BC", note: "Consensus: AB+A'C+BC = AB+A'C — BC is redundant." },
};

const BK_LAW_ROWS = [
  ["Identity", "A+0=A, A·1=A", "Neutral element, no change."],
  ["Null", "A+1=1, A·0=0", "Dominant element wins."],
  ["Idempotent", "A+A=A, A·A=A", "Repeats add nothing."],
  ["Complement", "A+A'=1, A·A'=0", "Covers every case."],
  ["Double negation", "(A')'=A", "Cancels out."],
  ["Commutative", "A+B=B+A", "Order-free."],
  ["Distributive", "A(B+C)=AB+AC", "AND over OR, or vice versa."],
  ["Absorption", "A+AB=A", "Bigger term already covers it."],
  ["De Morgan's", "(A+B)'=A'B'", "Flip operator, negate each term."],
  ["Consensus", "AB+A'C+BC=AB+A'C", "Third term is redundant."],
];

function bkEvaluate(raw) {
  const tokens = bkWithImplicitAnd(bkTokenize(raw));
  if (!tokens.length) throw new Error("Enter an expression first.");
  const vars = bkGetVariables(tokens);
  if (!vars.length) {
    const v = bkEvalRPN(bkToRPN(tokens), {});
    throw new Error(`No variables — this always equals ${v}. Use at least one of A–D.`);
  }
  const rpn = bkToRPN(tokens);

  const n = vars.length;
  const rows = [];
  for (let i = 0; i < Math.pow(2, n); i++) {
    const env = {};
    for (let j = 0; j < n; j++) env[vars[j]] = (i >> (n - 1 - j)) & 1;
    const out = bkEvalRPN(rpn, env);
    rows.push({ index: i, env, out });
  }
  return bkSolveRows(vars, n, rows);
}

/* Minimize from a truth-table output column. out is 1, 0, or "X" (don't care). */
function bkSolveRows(vars, n, rows) {
  const minterms = rows.filter((r) => r.out === 1).map((r) => r.index);
  const dontCares = rows.filter((r) => r.out === "X").map((r) => r.index);
  const maxterms = rows.filter((r) => r.out === 0).map((r) => r.index);

  const log = [];
  const qm = bkRunQM(minterms, n, vars, log, dontCares);

  let minimized, canonical;
  if (qm.allZero) { minimized = "0"; canonical = ""; }
  else if (qm.allOne) { minimized = "1"; canonical = ""; }
  else {
    minimized = qm.selected.map((pi) => bkBitsToExpr(pi.bits, vars) || "1").join(" + ");
    canonical = minterms.map((m) => bkBitsToExpr(bkToBin(m, n), vars)).join(" + ");
  }

  // POS: group the 0-cells (maxterms) with the same QM routine, then
  // turn each group into a sum term with complemented literals.
  let pos, posSelected = [];
  if (!maxterms.length) pos = "1";
  else if (!minterms.length) pos = "0";
  else {
    const qmPos = bkRunQM(maxterms, n, vars, [], dontCares);
    posSelected = qmPos.selected || [];
    pos = posSelected.map((pi) => {
      const lits = pi.bits.split("").map((b, i) => (b === "-" ? null : b === "0" ? vars[i] : vars[i] + "'")).filter(Boolean);
      return lits.length > 1 ? "(" + lits.join(" + ") + ")" : lits[0];
    }).join("");
  }

  return {
    vars, n, rows, minterms, dontCares, maxterms, log, pos, posSelected,
    selected: qm.selected || [],
    primes: qm.primes || [],
    essential: qm.essential || [],
    additional: qm.additional || null,
    allZero: !!qm.allZero,
    allOne: !!qm.allOne,
    minimized: minimized || "0", canonical,
  };
}

/* Build a result from K-map cells (index -> 0 / 1 / "X") using variables A..D. */
function bkFromCells(n, cells) {
  const vars = ["A", "B", "C", "D"].slice(0, n);
  const rows = [];
  for (let i = 0; i < Math.pow(2, n); i++) rows.push({ index: i, out: cells[i] ?? 0 });
  return bkSolveRows(vars, n, rows);
}

/* Parse "1, 3, 5-7" into indexes; throws on anything out of range. */
function bkParseIndexList(text, max, label) {
  const out = new Set();
  const parts = text.split(/[\s,;]+/).filter(Boolean);
  for (const part of parts) {
    const range = part.match(/^(\d+)-(\d+)$/);
    if (range) {
      const a = +range[1], b = +range[2];
      if (a > b) throw new Error(`${label}: "${part}" — range should go low to high.`);
      for (let i = a; i <= b; i++) out.add(i);
    } else if (/^\d+$/.test(part)) out.add(+part);
    else throw new Error(`${label}: "${part}" isn't a number. Use numbers like 1, 3, 5-7.`);
  }
  for (const v of out) if (v >= max) throw new Error(`${label}: ${v} is too big — with this many variables the cells go 0 to ${max - 1}.`);
  return [...out].sort((a, b) => a - b);
}

/* =========================================================
   Boolean Algebra screen
   ========================================================= */
function BooleanScreen({ onBack }) {
  const [expr, setExpr] = useState("AB' + A'B");
  const [preset, setPreset] = useState("custom");
  const [hover, setHover] = useState(null);
  const inputRef = useRef(null);

  const result = useMemo(() => {
    try {
      return bkEvaluate(expr);
    } catch (e) {
      return { err: e.message };
    }
  }, [expr]);
  const err = result.err;

  const insertSym = (sym) => {
    const el = inputRef.current;
    if (!el) return;
    const start = el.selectionStart ?? expr.length;
    const end = el.selectionEnd ?? expr.length;
    const next = expr.slice(0, start) + sym + expr.slice(end);
    setExpr(next);
    requestAnimationFrame(() => {
      el.focus();
      el.selectionStart = el.selectionEnd = start + sym.length;
    });
  };

  const applyPreset = (key) => {
    setPreset(key);
    const p = BK_PRESETS[key];
    if (p.expr !== null) setExpr(p.expr);
  };

  // dark "instrument module" palette shared with the other modules
  // accent follows the module's home-card color
  const bBg = "#181512", bPanel = "#211c17", bGold = "#A874E8", bGoldBright = "#cfb3f2";
  const bTeal = "#be97ee", bCream = "#f4efe4", bMuted = "#a89f8f", bLine = "#3a3327", bDanger = "#e8735a";

  // group essential-PI reasoning by prime, so one term lists every minterm it uniquely covers
  const essentialGroups = (() => {
    if (err || result.allZero || result.allOne) return [];
    const map = new Map();
    (result.essential || []).forEach(({ minterm, prime }) => {
      if (!map.has(prime)) map.set(prime, { prime, minterms: [] });
      map.get(prime).minterms.push(minterm);
    });
    return [...map.values()];
  })();

  const bStepTitle = { fontSize: 10.5, fontWeight: 700, color: bTeal, textTransform: "uppercase", letterSpacing: "0.04em", margin: "0 0 6px" };

  const bPanelStyle = { background: bPanel, borderRadius: 20, padding: 18, margin: "14px 22px 0 22px" };
  const bKeyBtn = { fontFamily: "monospace", fontSize: 12, background: bBg, border: `1px solid ${bGold}40`, color: bCream, borderRadius: 7, padding: "7px 10px", cursor: "pointer" };
  const bOpKey = { ...bKeyBtn, color: bGoldBright, borderColor: `${bGold}66` };

  return (
    <div className="screen-body">
      <div className="header">
        <div className="back neu" onClick={onBack} style={{ cursor: "pointer" }}>
          <BackIcon />
        </div>
        <div className="hlabel">MODULE &middot; BOOLEAN</div>
      </div>

      <div style={{ ...bPanelStyle, color: bCream, fontFamily: "Inter, Arial, sans-serif" }}>
        <p style={{ fontFamily: "monospace", fontSize: 10, letterSpacing: "0.14em", textTransform: "uppercase", color: bTeal, margin: "0 0 6px" }}>MOD.03</p>
        <h2 style={{ fontWeight: 800, fontSize: 20, margin: "0 0 4px", fontFamily: "'Baloo 2',sans-serif" }}>
          Boolean <span style={{ color: bGoldBright }}>Algebra</span>
        </h2>
        <p style={{ color: bMuted, fontSize: 11.5, margin: "0 0 14px", lineHeight: 1.4 }}>Enter an expression using A–D.</p>

        <input
          ref={inputRef}
          type="text"
          spellCheck={false}
          value={expr}
          onChange={(e) => { setExpr(e.target.value); setPreset("custom"); }}
          style={{ width: "100%", background: bBg, border: `1px solid ${bGold}4d`, color: bCream, fontFamily: "monospace", fontSize: 14, padding: "10px 12px", borderRadius: 9, outline: "none", boxSizing: "border-box" }}
        />
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 12 }}>
          {["A", "B", "C", "D"].map((s) => (
            <button key={s} style={bKeyBtn} onClick={() => insertSym(s)}>{s}</button>
          ))}
          <button style={bOpKey} onClick={() => insertSym("¬")} title="NOT">NOT</button>
          <button style={bOpKey} onClick={() => insertSym("∧")} title="AND">AND</button>
          <button style={bOpKey} onClick={() => insertSym("∨")} title="OR">OR</button>
          <button style={bOpKey} onClick={() => insertSym("⊕")} title="XOR">XOR</button>
          <button style={bKeyBtn} onClick={() => insertSym("(")}>(</button>
          <button style={bKeyBtn} onClick={() => insertSym(")")}>)</button>
          <button style={{ ...bKeyBtn, color: bDanger, borderColor: `${bDanger}66` }} onClick={() => setExpr("")}>Clear</button>
        </div>
        {err && <div style={{ marginTop: 10, color: bDanger, fontSize: 12 }}>{err}</div>}

        <p style={{ fontSize: 10.5, color: bMuted, margin: "16px 0 6px" }}>Theorem presets</p>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 6 }}>
          {Object.entries(BK_PRESETS).map(([key, p]) => (
            <button
              key={key}
              onClick={() => applyPreset(key)}
              style={{
                fontFamily: "monospace", fontSize: 11, borderRadius: 7, padding: "8px 8px", cursor: "pointer",
                border: `1px solid ${preset === key ? bTeal : bGold + "40"}`,
                background: preset === key ? bTeal + "1f" : bBg,
                color: preset === key ? bTeal : bCream,
              }}
            >
              {p.label}
            </button>
          ))}
        </div>
        {preset !== "custom" && BK_PRESETS[preset].note && (
          <p style={{ color: bMuted, fontSize: 11, marginTop: 10, lineHeight: 1.4 }}>{BK_PRESETS[preset].note}</p>
        )}
      </div>

      <div style={bPanelStyle}>
        <p style={{ fontFamily: "monospace", fontSize: 10, color: bMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 8px" }}>Minimized SOP</p>
        <div style={{ fontSize: 18, fontWeight: 700, color: bGoldBright, fontFamily: "monospace", wordBreak: "break-word" }}>{err ? "—" : result.minimized}</div>
        {!err && result.canonical && result.canonical !== result.minimized && (
          <div style={{ color: bMuted, fontSize: 11, marginTop: 6 }}>Sum of minterms: {result.canonical}</div>
        )}
      </div>

      <div style={bPanelStyle}>
        <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 10px", fontFamily: "'Baloo 2',sans-serif" }}>Truth table</h3>
        {err ? (
          <div style={{ color: bMuted, fontSize: 12 }}>—</div>
        ) : (
          <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: "monospace", fontSize: 12.5, textAlign: "center" }}>
            <thead>
              <tr>
                {result.vars.map((v) => <th key={v} style={{ color: bMuted, padding: "3px 5px" }}>{v}</th>)}
                <th style={{ color: bGold, padding: "3px 5px" }}>F</th>
              </tr>
            </thead>
            <tbody>
              {result.rows.map((r) => (
                <tr
                  key={r.index}
                  onMouseEnter={() => setHover(r.index)}
                  onMouseLeave={() => setHover(null)}
                  style={{ background: hover === r.index ? `${bTeal}1a` : "transparent" }}
                >
                  {result.vars.map((v) => <td key={v} style={{ padding: "3px 5px" }}>{r.env[v]}</td>)}
                  <td style={{ padding: "3px 5px", color: r.out ? bTeal : bMuted, fontWeight: 700 }}>{r.out}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <div style={{ ...bPanelStyle, marginBottom: 26 }}>
        <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 4px", fontFamily: "'Baloo 2',sans-serif" }}>Step-by-step simplification</h3>
        <p style={{ color: bMuted, fontSize: 11, margin: "0 0 12px", lineHeight: 1.4 }}>
          How the minimized expression was derived, using Quine–McCluskey grouping.
        </p>

        {err ? (
          <div style={{ color: bMuted, fontSize: 12 }}>—</div>
        ) : result.allZero ? (
          <div style={{ color: bMuted, fontSize: 12, fontFamily: "monospace" }}>F is 0 for every input — nothing to simplify.</div>
        ) : result.allOne ? (
          <div style={{ color: bMuted, fontSize: 12, fontFamily: "monospace" }}>F is 1 for every input — minimizes straight to 1.</div>
        ) : (
          <>
            <div style={{ paddingTop: 2 }}>
              <p style={bStepTitle}>Step 1 · Minterms where F = 1</p>
              <p style={{ fontFamily: "monospace", fontSize: 12, color: bCream, lineHeight: 1.6 }}>
                {result.minterms.map((m) => `${m} (${bkToBin(m, result.n)})`).join(",  ")}
              </p>
            </div>

            <div style={{ borderTop: `1px solid ${bLine}`, paddingTop: 10, marginTop: 10 }}>
              <p style={bStepTitle}>Step 2 · Combine adjacent groups</p>
              {result.log.length === 0 ? (
                <p style={{ color: bMuted, fontSize: 12, fontFamily: "monospace" }}>No two groups differ by exactly one variable — nothing merges.</p>
              ) : (
                <div style={{ maxHeight: 200, overflowY: "auto" }}>
                  {(() => {
                    let lastRound = null;
                    return result.log.map((m, i) => {
                      const showRound = m.round !== lastRound;
                      lastRound = m.round;
                      return (
                        <div key={i}>
                          {showRound && (
                            <p style={{ fontSize: 9.5, color: bMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: i === 0 ? "0 0 4px" : "10px 0 4px" }}>
                              Round {m.round}
                            </p>
                          )}
                          <div style={{ fontFamily: "monospace", fontSize: 11, color: bCream, padding: "2px 0" }}>
                            {m.aMinterms.join(",")} ({m.aBits}) + {m.bMinterms.join(",")} ({m.bBits}) → {m.resultBits}, eliminating{" "}
                            <span style={{ color: bGoldBright }}>{m.eliminatedVar}</span>
                          </div>
                        </div>
                      );
                    });
                  })()}
                </div>
              )}
            </div>

            <div style={{ borderTop: `1px solid ${bLine}`, paddingTop: 10, marginTop: 10 }}>
              <p style={bStepTitle}>Step 3 · Resulting prime implicants</p>
              {result.primes.map((p, i) => (
                <div key={i} style={{ fontFamily: "monospace", fontSize: 12, color: bCream, padding: "2px 0" }}>
                  {bkBitsToExpr(p.bits, result.vars) || "1"}{" "}
                  <span style={{ color: bMuted, fontFamily: "Inter, Arial, sans-serif" }}>— covers {"{"}{p.minterms.join(", ")}{"}"}</span>
                </div>
              ))}
            </div>

            <div style={{ borderTop: `1px solid ${bLine}`, paddingTop: 10, marginTop: 10 }}>
              <p style={bStepTitle}>Step 4 · Choose essential prime implicants</p>
              {essentialGroups.length === 0 ? (
                <p style={{ color: bMuted, fontSize: 12 }}>No prime implicant is the only cover of any minterm — selection continues below.</p>
              ) : (
                essentialGroups.map((g, i) => (
                  <div key={i} style={{ fontSize: 11.5, color: bCream, padding: "2px 0", lineHeight: 1.5 }}>
                    <span style={{ fontFamily: "monospace", color: bGoldBright, fontWeight: 700 }}>{bkBitsToExpr(g.prime.bits, result.vars) || "1"}</span>{" "}
                    is essential — the only implicant covering minterm{g.minterms.length > 1 ? "s" : ""} {g.minterms.join(", ")}.
                  </div>
                ))
              )}
            </div>

            <div style={{ borderTop: `1px solid ${bLine}`, paddingTop: 10, marginTop: 10 }}>
              <p style={bStepTitle}>Step 5 · Cover any remaining minterms</p>
              {result.additional ? (
                <p style={{ fontSize: 11.5, color: bCream, lineHeight: 1.5 }}>
                  Minterm{result.additional.uncovered.length > 1 ? "s" : ""} {result.additional.uncovered.join(", ")}{" "}
                  {result.additional.uncovered.length > 1 ? "aren't" : "isn't"} covered by an essential implicant, so{" "}
                  {result.additional.added.map((p, i) => (
                    <span key={i}>
                      <span style={{ fontFamily: "monospace", color: bGoldBright, fontWeight: 700 }}>{bkBitsToExpr(p.bits, result.vars) || "1"}</span>
                      {i < result.additional.added.length - 1 ? " and " : ""}
                    </span>
                  ))}{" "}
                  {result.additional.added.length > 1 ? "are" : "is"} added to complete the cover.
                </p>
              ) : (
                <p style={{ color: bMuted, fontSize: 12 }}>Essential prime implicants alone already cover every minterm — nothing more to add.</p>
              )}
            </div>

            <div style={{ borderTop: `1px solid ${bLine}`, paddingTop: 10, marginTop: 10 }}>
              <p style={bStepTitle}>Step 6 · Final expression</p>
              <p style={{ fontFamily: "monospace", fontSize: 14, color: bGoldBright, fontWeight: 700 }}>F = {result.minimized}</p>
            </div>
          </>
        )}
      </div>

      <div style={{ ...bPanelStyle, marginBottom: 26 }}>
        <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 12px", fontFamily: "'Baloo 2',sans-serif" }}>Law reference</h3>
        {BK_LAW_ROWS.map(([name, formula, note]) => (
          <div key={name} style={{ borderTop: `1px solid ${bLine}`, padding: "8px 0" }}>
            <div style={{ display: "flex", justifyContent: "space-between", gap: 8 }}>
              <span style={{ color: bGold, fontWeight: 600, fontSize: 11.5 }}>{name}</span>
              <span style={{ fontFamily: "monospace", color: bCream, fontSize: 11.5, textAlign: "right" }}>{formula}</span>
            </div>
            <div style={{ color: bMuted, fontSize: 10.5, marginTop: 2 }}>{note}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

/* =========================================================
   Karnaugh Map screen
   ========================================================= */
/* =========================================================
   Logic circuit builder (used by the K-map "Circuit" mode)
   Nodes: inputs (A–D), gates, outputs. Wires go from an output
   pin to a gate/output input pin. Evaluated into a truth table.
   ========================================================= */
const CK_GATES = ["AND", "OR", "NOT", "NAND", "NOR", "XOR", "XNOR"];
const CK_VARS = ["A", "B", "C", "D"];
const CK_OUT_NAMES = ["F", "G", "H", "Y", "Z", "W", "P", "Q"];
// each input variable gets its own wire color so A, B, C and D are easy to trace
const CK_VAR_COLORS = { A: "#FF7B72", B: "#5AB0FF", C: "#FFD166", D: "#C792EA" };
const CK_IO_W = 46, CK_IO_H = 28, CK_GATE_W = 58;

function ckGateH(k) { return Math.max(44, 16 * k + 12); }
function ckInCount(node) { return node.kind === "gate" ? (node.gate === "NOT" ? 1 : node.inputs) : node.kind === "out" ? 1 : 0; }
function ckSize(node) {
  if (node.kind === "gate") return { w: CK_GATE_W, h: ckGateH(ckInCount(node)) };
  return { w: CK_IO_W, h: CK_IO_H };
}
function ckInPin(node, i) {
  if (node.kind === "out") return { x: node.x, y: node.y + CK_IO_H / 2 };
  const h = ckSize(node).h, k = ckInCount(node);
  return { x: node.x, y: node.y + ((i + 1) * h) / (k + 1) };
}
function ckOutPin(node) {
  const { w, h } = ckSize(node);
  return { x: node.x + w, y: node.y + h / 2 };
}

function ckApply(gate, vals) {
  const and = vals.every((v) => v === 1) ? 1 : 0;
  const or = vals.some((v) => v === 1) ? 1 : 0;
  const xor = vals.reduce((a, v) => a ^ v, 0);
  switch (gate) {
    case "AND": return and;
    case "OR": return or;
    case "NOT": return vals[0] ? 0 : 1;
    case "NAND": return and ? 0 : 1;
    case "NOR": return or ? 0 : 1;
    case "XOR": return xor;
    case "XNOR": return xor ? 0 : 1;
    default: return 0;
  }
}

function ckGateLabel(node, idx) {
  return `${node.gate} gate #${idx}`;
}

/* Evaluate the circuit. Returns { vars, n, outputs, rows, exprs } or throws a friendly error. */
function ckEvaluate(nodes, wires) {
  const byId = Object.fromEntries(nodes.map((nd) => [nd.id, nd]));
  const inputs = nodes.filter((nd) => nd.kind === "in");
  const outputs = nodes.filter((nd) => nd.kind === "out");
  if (!inputs.length) throw new Error("Add at least one input (A–D).");
  if (!outputs.length) throw new Error("Add an output so there's something to solve.");
  const vars = CK_VARS.filter((v) => inputs.some((nd) => nd.v === v));
  const n = vars.length;
  const feed = {};
  wires.forEach((w) => (feed[w.to + ":" + w.pin] = w.from));
  const gateIdx = {};
  nodes.filter((nd) => nd.kind === "gate").forEach((nd, i) => (gateIdx[nd.id] = i + 1));

  // check every input pin is connected
  for (const nd of nodes) {
    const k = ckInCount(nd);
    for (let i = 0; i < k; i++) {
      if (!feed[nd.id + ":" + i]) {
        if (nd.kind === "out") throw new Error(`Output ${nd.label} isn't connected yet.`);
        throw new Error(`${ckGateLabel(nd, gateIdx[nd.id])} has an empty input — wire it up.`);
      }
    }
  }

  const evalNode = (id, env, seen) => {
    const nd = byId[id];
    if (nd.kind === "in") return env[nd.v];
    if (seen.has(id)) throw new Error("The circuit loops back on itself — remove the feedback wire.");
    seen.add(id);
    const vals = [];
    for (let i = 0; i < ckInCount(nd); i++) vals.push(evalNode(feed[id + ":" + i], env, seen));
    seen.delete(id);
    return nd.kind === "out" ? vals[0] : ckApply(nd.gate, vals);
  };

  const rows = [];
  for (let i = 0; i < Math.pow(2, n); i++) {
    const env = {};
    vars.forEach((v, j) => (env[v] = (i >> (n - 1 - j)) & 1));
    const outs = {};
    outputs.forEach((o) => (outs[o.id] = evalNode(o.id, env, new Set())));
    rows.push({ index: i, env, outs });
  }

  // unsimplified expression straight from the wiring, for reference
  const exprOf = (id, seen) => {
    const nd = byId[id];
    if (nd.kind === "in") return nd.v;
    if (seen.has(id)) return "?";
    seen.add(id);
    const parts = [];
    for (let i = 0; i < ckInCount(nd); i++) parts.push(exprOf(feed[id + ":" + i], seen));
    seen.delete(id);
    if (nd.kind === "out") return parts[0];
    const wrap = (p) => (p.length > 2 ? "(" + p + ")" : p);
    switch (nd.gate) {
      case "NOT": return wrap(parts[0]) + "'";
      case "AND": return parts.map(wrap).join("");
      case "OR": return parts.join(" + ");
      case "XOR": return parts.map(wrap).join(" ⊕ ");
      case "NAND": return "(" + parts.map(wrap).join("") + ")'";
      case "NOR": return "(" + parts.join(" + ") + ")'";
      case "XNOR": return "(" + parts.map(wrap).join(" ⊕ ") + ")'";
      default: return "?";
    }
  };
  const exprs = Object.fromEntries(outputs.map((o) => [o.id, exprOf(o.id, new Set())]));
  return { vars, n, outputs, rows, exprs };
}

/* Live signal on every node for the current input switches; null = not wired yet. */
function ckSignals(nodes, wires, env) {
  const byId = Object.fromEntries(nodes.map((nd) => [nd.id, nd]));
  const feed = {};
  wires.forEach((w) => (feed[w.to + ":" + w.pin] = w.from));
  const memo = {};
  const val = (id, seen) => {
    if (id in memo) return memo[id];
    const nd = byId[id];
    if (!nd) return null;
    if (nd.kind === "in") return (memo[id] = env[nd.v] ? 1 : 0);
    if (seen.has(id)) return null;
    seen.add(id);
    const vals = [];
    for (let i = 0; i < ckInCount(nd); i++) {
      const src = feed[id + ":" + i];
      const v = src ? val(src, seen) : null;
      if (v === null) { seen.delete(id); return (memo[id] = null); }
      vals.push(v);
    }
    seen.delete(id);
    return (memo[id] = nd.kind === "out" ? vals[0] : ckApply(nd.gate, vals));
  };
  nodes.forEach((nd) => val(nd.id, new Set()));
  return memo;
}

/* Starter circuits */
let ckSeq = 1;
const ckId = () => "n" + ckSeq++;
function ckExampleSOP() {
  // F = AB + A'C  (the classic AND-OR circuit)
  const a = { id: ckId(), kind: "in", v: "A", x: 8, y: 20 };
  const b = { id: ckId(), kind: "in", v: "B", x: 8, y: 80 };
  const c = { id: ckId(), kind: "in", v: "C", x: 8, y: 200 };
  const not = { id: ckId(), kind: "gate", gate: "NOT", inputs: 1, x: 70, y: 120 };
  const g1 = { id: ckId(), kind: "gate", gate: "AND", inputs: 2, x: 150, y: 30 };
  const g2 = { id: ckId(), kind: "gate", gate: "AND", inputs: 2, x: 150, y: 150 };
  const or = { id: ckId(), kind: "gate", gate: "OR", inputs: 2, x: 235, y: 90 };
  const f = { id: ckId(), kind: "out", label: "F", x: 312, y: 104 };
  const nodes = [a, b, c, not, g1, g2, or, f];
  const wires = [
    { from: a.id, to: g1.id, pin: 0 }, { from: b.id, to: g1.id, pin: 1 },
    { from: a.id, to: not.id, pin: 0 }, { from: not.id, to: g2.id, pin: 0 }, { from: c.id, to: g2.id, pin: 1 },
    { from: g1.id, to: or.id, pin: 0 }, { from: g2.id, to: or.id, pin: 1 },
    { from: or.id, to: f.id, pin: 0 },
  ];
  return { nodes, wires };
}
function ckExampleDecoder() {
  // 2-to-4 decoder: F=A'B', G=A'B, H=AB', Y=AB
  const a = { id: ckId(), kind: "in", v: "A", x: 6, y: 30 };
  const b = { id: ckId(), kind: "in", v: "B", x: 6, y: 210 };
  const na = { id: ckId(), kind: "gate", gate: "NOT", inputs: 1, x: 62, y: 70 };
  const nb = { id: ckId(), kind: "gate", gate: "NOT", inputs: 1, x: 62, y: 160 };
  const gs = [0, 1, 2, 3].map((i) => ({ id: ckId(), kind: "gate", gate: "AND", inputs: 2, x: 190, y: 8 + i * 66 }));
  const outs = ["F", "G", "H", "Y"].map((l, i) => ({ id: ckId(), kind: "out", label: l, x: 290, y: 16 + i * 66 }));
  const src = [[na, nb], [na, b], [a, nb], [a, b]];
  const wires = [{ from: a.id, to: na.id, pin: 0 }, { from: b.id, to: nb.id, pin: 0 }];
  gs.forEach((g, i) => {
    wires.push({ from: src[i][0].id, to: g.id, pin: 0 }, { from: src[i][1].id, to: g.id, pin: 1 }, { from: g.id, to: outs[i].id, pin: 0 });
  });
  return { nodes: [a, b, na, nb, ...gs, ...outs], wires };
}

function CkGateShape({ gate, h, stroke, fill }) {
  const bubble = gate === "NAND" || gate === "NOR" || gate === "XNOR" || gate === "NOT";
  const bodyEnd = bubble ? 47 : 52;
  let body;
  if (gate === "AND" || gate === "NAND") {
    body = <path d={`M8 0 H24 Q${bodyEnd} 0 ${bodyEnd} ${h / 2} Q${bodyEnd} ${h} 24 ${h} H8 Z`} />;
  } else if (gate === "NOT") {
    body = <path d={`M10 ${h / 2 - 15} L${bodyEnd} ${h / 2} L10 ${h / 2 + 15} Z`} />;
  } else {
    body = (
      <>
        <path d={`M8 0 Q30 0 ${bodyEnd} ${h / 2} Q30 ${h} 8 ${h} Q18 ${h / 2} 8 0 Z`} />
        {(gate === "XOR" || gate === "XNOR") && <path d={`M3 0 Q13 ${h / 2} 3 ${h}`} fill="none" />}
      </>
    );
  }
  return (
    <g stroke={stroke} strokeWidth="1.8" fill={fill}>
      {body}
      {bubble && <circle cx={bodyEnd + 3.5} cy={h / 2} r="3.5" />}
    </g>
  );
}

function CircuitEditor({ nodes, setNodes, wires, setWires, colors, levels, setLevels }) {
  const { bg, line, gold, bright, teal, cream, muted, danger } = colors;
  const svgRef = useRef(null);
  const drag = useRef(null);
  const [sel, setSel] = useState(null); // { type: "node"|"wire", id }
  const [pending, setPending] = useState(null); // { kind: "out", id } or { kind: "in", id, pin }
  const VW = 360, VH = 290;

  const byId = Object.fromEntries(nodes.map((nd) => [nd.id, nd]));
  const selNode = sel && sel.type === "node" ? byId[sel.id] : null;
  const sig = useMemo(() => ckSignals(nodes, wires, levels), [nodes, wires, levels]);
  const toggleLevel = (v) => setLevels((l) => ({ ...l, [v]: l[v] ? 0 : 1 }));

  const toSvg = (e) => {
    const svg = svgRef.current;
    const pt = svg.createSVGPoint();
    pt.x = e.clientX; pt.y = e.clientY;
    return pt.matrixTransform(svg.getScreenCTM().inverse());
  };

  const place = () => {
    const k = nodes.length;
    return { x: 20 + ((k * 47) % 250), y: 20 + ((k * 61) % 220) };
  };
  const addInput = () => {
    const used = new Set(nodes.filter((nd) => nd.kind === "in").map((nd) => nd.v));
    const v = CK_VARS.find((x) => !used.has(x)) || "A";
    const nd = { id: ckId(), kind: "in", v, ...place(), x: 6 };
    setNodes([...nodes, nd]); setSel({ type: "node", id: nd.id });
  };
  const addOutput = () => {
    const used = new Set(nodes.filter((nd) => nd.kind === "out").map((nd) => nd.label));
    const label = CK_OUT_NAMES.find((x) => !used.has(x)) || "F";
    const nd = { id: ckId(), kind: "out", label, ...place(), x: VW - CK_IO_W - 6 };
    setNodes([...nodes, nd]); setSel({ type: "node", id: nd.id });
  };
  const addGate = (gate) => {
    const nd = { id: ckId(), kind: "gate", gate, inputs: gate === "NOT" ? 1 : 2, ...place(), x: 120 + ((nodes.length * 23) % 120) };
    setNodes([...nodes, nd]); setSel({ type: "node", id: nd.id });
  };
  const removeSelected = () => {
    if (!sel) return;
    if (sel.type === "node") {
      setNodes(nodes.filter((nd) => nd.id !== sel.id));
      setWires(wires.filter((w) => w.from !== sel.id && w.to !== sel.id));
    } else {
      setWires(wires.filter((_, i) => "w" + i !== sel.id));
    }
    setSel(null); setPending(null);
  };
  const setInputs = (k) => {
    if (!selNode || selNode.kind !== "gate" || selNode.gate === "NOT") return;
    const kk = Math.max(2, Math.min(4, k));
    setNodes(nodes.map((nd) => (nd.id === selNode.id ? { ...nd, inputs: kk } : nd)));
    setWires(wires.filter((w) => !(w.to === selNode.id && w.pin >= kk)));
  };
  const setVar = (v) => setNodes(nodes.map((nd) => (nd.id === selNode.id ? { ...nd, v } : nd)));

  const connect = (fromId, toId, pin) => {
    if (fromId === toId) return;
    setWires([...wires.filter((w) => !(w.to === toId && w.pin === pin)), { from: fromId, to: toId, pin }]);
  };
  const tapOutPin = (e, id) => {
    e.stopPropagation();
    if (pending && pending.kind === "in") { connect(id, pending.id, pending.pin); setPending(null); return; }
    setPending(pending && pending.kind === "out" && pending.id === id ? null : { kind: "out", id });
  };
  const tapInPin = (e, id, pin) => {
    e.stopPropagation();
    if (pending && pending.kind === "out") { connect(pending.id, id, pin); setPending(null); return; }
    setPending(pending && pending.kind === "in" && pending.id === id && pending.pin === pin ? null : { kind: "in", id, pin });
  };

  const onNodeDown = (e, nd) => {
    e.stopPropagation();
    const p = toSvg(e);
    drag.current = { id: nd.id, dx: p.x - nd.x, dy: p.y - nd.y, sx: p.x, sy: p.y, moved: false };
    svgRef.current.setPointerCapture(e.pointerId);
    setSel({ type: "node", id: nd.id });
  };
  const onMove = (e) => {
    const d = drag.current;
    if (!d) return;
    const p = toSvg(e);
    const nd = byId[d.id];
    if (!nd) return;
    if (!d.moved && Math.hypot(p.x - d.sx, p.y - d.sy) < 4) return; // still a tap
    const { w, h } = ckSize(nd);
    const x = Math.max(0, Math.min(VW - w, p.x - d.dx));
    const y = Math.max(0, Math.min(VH - h, p.y - d.dy));
    d.moved = true;
    setNodes((prev) => prev.map((m) => (m.id === d.id ? { ...m, x, y } : m)));
  };
  const onUp = () => {
    const d = drag.current;
    drag.current = null;
    // a tap (not a drag) on an input flips it between 0 and 1
    if (d && !d.moved) {
      const nd = byId[d.id];
      if (nd && nd.kind === "in") toggleLevel(nd.v);
    }
  };

  const chip = (active) => ({
    fontFamily: "monospace", fontSize: 11, borderRadius: 7, padding: "6px 9px", cursor: "pointer",
    border: `1px solid ${active ? gold : gold + "40"}`, background: active ? gold : bg, color: active ? bg : cream, fontWeight: 700,
  });

  return (
    <div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 5, marginBottom: 8 }}>
        <button style={{ ...chip(false), color: teal }} onClick={addInput}>+ Input</button>
        <button style={{ ...chip(false), color: bright }} onClick={addOutput}>+ Output</button>
        {CK_GATES.map((g) => (
          <button key={g} style={chip(false)} onClick={() => addGate(g)}>{g}</button>
        ))}
      </div>

      {(() => {
        const used = CK_VARS.filter((v) => nodes.some((nd) => nd.kind === "in" && nd.v === v));
        if (!used.length) return null;
        return (
          <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 8, flexWrap: "wrap" }}>
            <span style={{ fontSize: 11, color: muted }}>Inputs</span>
            {used.map((v) => (
              <button key={v} onClick={() => toggleLevel(v)} aria-label={`${v} is ${levels[v] ? 1 : 0}, tap to switch`}
                style={{
                  display: "flex", alignItems: "center", gap: 6, borderRadius: 999, padding: "4px 10px 4px 8px", cursor: "pointer",
                  border: `1.5px solid ${CK_VAR_COLORS[v]}`, background: levels[v] ? CK_VAR_COLORS[v] : "transparent",
                  color: levels[v] ? bg : cream, fontFamily: "monospace", fontWeight: 800, fontSize: 12,
                }}>
                {v} = {levels[v] ? 1 : 0}
              </button>
            ))}
            {nodes.filter((nd) => nd.kind === "out").map((o) => {
              const v = sig[o.id];
              return (
                <span key={o.id} style={{ marginLeft: 4, fontFamily: "monospace", fontWeight: 800, fontSize: 12, color: v === 1 ? bright : muted }}>
                  {o.label} = {v === null || v === undefined ? "?" : v}
                </span>
              );
            })}
          </div>
        );
      })()}

      <div style={{ position: "relative", background: bg, borderRadius: 12, border: `1px solid ${line}` }}>
        <svg
          ref={svgRef}
          viewBox={`0 0 ${VW} ${VH}`}
          width="100%"
          style={{ display: "block", touchAction: "none", userSelect: "none" }}
          onPointerMove={onMove}
          onPointerUp={onUp}
          onPointerCancel={onUp}
          onPointerDown={() => { setSel(null); setPending(null); }}
        >
          <defs>
            <pattern id="ckgrid" width="20" height="20" patternUnits="userSpaceOnUse">
              <circle cx="1" cy="1" r="0.8" fill={line} />
            </pattern>
          </defs>
          <rect width={VW} height={VH} fill="url(#ckgrid)" />

          {/* wires */}
          {wires.map((w, i) => {
            const a = byId[w.from], b = byId[w.to];
            if (!a || !b) return null;
            const p = ckOutPin(a), q = ckInPin(b, w.pin);
            const mid = Math.max(18, Math.abs(q.x - p.x) / 2);
            const d = `M${p.x} ${p.y} C${p.x + mid} ${p.y} ${q.x - mid} ${q.y} ${q.x} ${q.y}`;
            const on = sel && sel.type === "wire" && sel.id === "w" + i;
            // wires leaving an input take that variable's color; gate outputs stay neutral
            const wireColor = a.kind === "in" ? CK_VAR_COLORS[a.v] : cream;
            const level = sig[a.id];
            return (
              <g key={i} onPointerDown={(e) => { e.stopPropagation(); setSel({ type: "wire", id: "w" + i }); setPending(null); }} style={{ cursor: "pointer" }}>
                <path d={d} stroke="transparent" strokeWidth="12" fill="none" />
                {level === 1 && !on && <path d={d} stroke={wireColor} strokeWidth="6" strokeOpacity="0.22" fill="none" />}
                <path d={d} stroke={on ? danger : wireColor} strokeWidth={on ? 2.8 : level === 1 ? 2.6 : 1.8}
                  strokeOpacity={on ? 1 : level === 0 ? 0.38 : 1}
                  strokeDasharray={on ? "5 3" : undefined} fill="none" />
              </g>
            );
          })}

          {/* nodes */}
          {nodes.map((nd) => {
            const { w, h } = ckSize(nd);
            const isSel = sel && sel.type === "node" && sel.id === nd.id;
            const stroke = isSel ? bright : cream;
            const k = ckInCount(nd);
            const op = ckOutPin(nd);
            return (
              <g key={nd.id}>
                <g transform={`translate(${nd.x} ${nd.y})`} onPointerDown={(e) => onNodeDown(e, nd)} style={{ cursor: "grab" }}>
                  {nd.kind === "gate" ? (
                    <>
                      <rect x="0" y="0" width={w} height={h} fill="transparent" />
                      <CkGateShape gate={nd.gate} h={h} stroke={stroke} fill="#2a241d" />
                      <text x="27" y={h / 2 + 3} textAnchor="middle" fontSize="8" fill={muted} fontFamily="monospace" style={{ pointerEvents: "none" }}>
                        {nd.gate === "NOT" ? "" : nd.gate}
                      </text>
                    </>
                  ) : (
                    <>
                      <rect x="0" y="0" width={w} height={h} rx={nd.kind === "in" ? 14 : 6}
                        fill={nd.kind === "in" ? CK_VAR_COLORS[nd.v] + (sig[nd.id] ? "55" : "22") : sig[nd.id] === 1 ? bright + "55" : gold + "22"}
                        stroke={isSel ? bright : nd.kind === "in" ? CK_VAR_COLORS[nd.v] : stroke} strokeWidth={isSel ? 2.2 : 1.6} />
                      <text x={nd.kind === "in" ? 13 : 12} y={h / 2 + 5} textAnchor="middle" fontSize="14" fontWeight="700" fill={cream} fontFamily="monospace" style={{ pointerEvents: "none" }}>
                        {nd.kind === "in" ? nd.v : nd.label}
                      </text>
                      {(() => {
                        const v = sig[nd.id];
                        const lit = v === 1;
                        const c = nd.kind === "in" ? CK_VAR_COLORS[nd.v] : bright;
                        return (
                          <g style={{ pointerEvents: "none" }}>
                            <rect x={w - 19} y="6" width="15" height={h - 12} rx="4" fill={lit ? c : bg} stroke={c} strokeWidth="1.2" />
                            <text x={w - 11.5} y={h / 2 + 4} textAnchor="middle" fontSize="11" fontWeight="800" fontFamily="monospace" fill={lit ? bg : cream}>
                              {v === null || v === undefined ? "?" : v}
                            </text>
                          </g>
                        );
                      })()}
                    </>
                  )}
                </g>
                {/* input pins */}
                {Array.from({ length: k }, (_, i) => {
                  const p = ckInPin(nd, i);
                  const pend = pending && pending.kind === "in" && pending.id === nd.id && pending.pin === i;
                  const feedWire = wires.find((wr) => wr.to === nd.id && wr.pin === i);
                  const filled = !!feedWire;
                  const src = feedWire && byId[feedWire.from];
                  const pinColor = src ? (src.kind === "in" ? CK_VAR_COLORS[src.v] : cream) : teal;
                  return (
                    <g key={"i" + i} onPointerDown={(e) => tapInPin(e, nd.id, i)} style={{ cursor: "crosshair" }}>
                      <circle cx={p.x} cy={p.y} r="11" fill="transparent" />
                      <circle cx={p.x} cy={p.y} r={pend ? 6 : 4.5} fill={pend ? bright : filled ? pinColor : bg} stroke={pend ? bright : pinColor} strokeWidth="1.6" />
                    </g>
                  );
                })}
                {nd.kind === "gate" && sig[nd.id] !== null && sig[nd.id] !== undefined && (
                  <text x={op.x - 2} y={op.y - 8} textAnchor="end" fontSize="9" fontWeight="800" fontFamily="monospace"
                    fill={sig[nd.id] ? bright : muted} style={{ pointerEvents: "none" }}>{sig[nd.id]}</text>
                )}
                {/* output pin */}
                {nd.kind !== "out" && (
                  <g onPointerDown={(e) => tapOutPin(e, nd.id)} style={{ cursor: "crosshair" }}>
                    <circle cx={op.x} cy={op.y} r="11" fill="transparent" />
                    <circle cx={op.x} cy={op.y} r={pending && pending.kind === "out" && pending.id === nd.id ? 6 : 4.5}
                      fill={pending && pending.kind === "out" && pending.id === nd.id ? bright : nd.kind === "in" ? CK_VAR_COLORS[nd.v] : gold}
                      stroke={nd.kind === "in" ? CK_VAR_COLORS[nd.v] : bright} strokeWidth="1.4" />
                  </g>
                )}
              </g>
            );
          })}

          {!nodes.length && (
            <text x={VW / 2} y={VH / 2} textAnchor="middle" fontSize="12" fill={muted}>Add inputs, gates and an output above</text>
          )}
        </svg>
      </div>

      <p style={{ fontSize: 10.5, color: muted, margin: "8px 0 0", lineHeight: 1.45 }}>
        {pending
          ? pending.kind === "out" ? "Now tap an input pin (left side) to connect." : "Now tap an output pin (right side) to connect."
          : "Tap an input (A–D) to switch it between 0 and 1 and watch the signal flow. Drag parts to move them. To wire: tap the dot on the right of a part, then a dot on the left of another. Tap a wire or part, then Delete."}
      </p>

      {sel && (
        <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: 6, marginTop: 8 }}>
          {selNode && selNode.kind === "in" && CK_VARS.map((v) => (
            <button key={v} style={{ ...chip(selNode.v === v), ...(selNode.v === v ? { background: CK_VAR_COLORS[v], borderColor: CK_VAR_COLORS[v] } : { color: CK_VAR_COLORS[v] }) }}
              onClick={() => setVar(v)}>{v}</button>
          ))}
          {selNode && selNode.kind === "gate" && selNode.gate !== "NOT" && (
            <>
              <span style={{ fontSize: 11, color: muted }}>Inputs</span>
              <button style={chip(false)} onClick={() => setInputs(selNode.inputs - 1)}>−</button>
              <span style={{ fontSize: 12, color: cream, fontFamily: "monospace" }}>{selNode.inputs}</span>
              <button style={chip(false)} onClick={() => setInputs(selNode.inputs + 1)}>+</button>
            </>
          )}
          <button style={{ ...chip(false), color: danger, borderColor: danger + "66", marginLeft: "auto" }} onClick={removeSelected}>
            Delete {sel.type === "wire" ? "wire" : selNode ? (selNode.kind === "gate" ? selNode.gate : selNode.kind === "in" ? "input" : "output") : ""}
          </button>
        </div>
      )}
    </div>
  );
}

function KMapScreen({ onBack }) {
  const [mode, setMode] = useState("expr"); // expr | table | minterms | circuit
  const [circuit, setCircuit] = useState(() => ckExampleSOP());
  const [outId, setOutId] = useState(null);
  const [levels, setLevels] = useState({ A: 0, B: 0, C: 0, D: 0 });
  const setCkNodes = (v) => setCircuit((c) => ({ ...c, nodes: typeof v === "function" ? v(c.nodes) : v }));
  const setCkWires = (v) => setCircuit((c) => ({ ...c, wires: typeof v === "function" ? v(c.wires) : v }));
  const ck = useMemo(() => {
    if (mode !== "circuit") return null;
    try { return ckEvaluate(circuit.nodes, circuit.wires); } catch (e) { return { err: e.message }; }
  }, [mode, circuit]);
  const [expr, setExpr] = useState("AB' + A'B");
  const [preset, setPreset] = useState("custom");
  const [nVars, setNVars] = useState(3);
  const [cells, setCells] = useState({});
  const [mText, setMText] = useState("1, 3, 5, 7");
  const [dText, setDText] = useState("");
  const inputRef = useRef(null);

  const result = useMemo(() => {
    try {
      if (mode === "table") return bkFromCells(nVars, cells);
      if (mode === "circuit") {
        if (ck.err) throw new Error(ck.err);
        const o = ck.outputs.find((x) => x.id === outId) || ck.outputs[0];
        const rows = ck.rows.map((row) => ({ index: row.index, env: row.env, out: row.outs[o.id] }));
        return { ...bkSolveRows(ck.vars, ck.n, rows), circuitOut: o };
      }
      if (mode === "minterms") {
        const max = Math.pow(2, nVars);
        const ones = bkParseIndexList(mText, max, "Minterms");
        const dcs = bkParseIndexList(dText, max, "Don't cares");
        const clash = ones.find((m) => dcs.includes(m));
        if (clash !== undefined) throw new Error(`${clash} is in both lists — a cell is either 1 or don't care.`);
        const c = {};
        ones.forEach((m) => (c[m] = 1));
        dcs.forEach((m) => (c[m] = "X"));
        return bkFromCells(nVars, c);
      }
      return bkEvaluate(expr);
    } catch (e) {
      return { err: e.message };
    }
  }, [mode, expr, nVars, cells, mText, dText, ck, outId]);
  const err = result.err;

  // tap a cell in table mode: 0 -> 1 -> X -> 0
  const cycleCell = (idx) => {
    setCells((c) => {
      const cur = c[idx] ?? 0;
      const next = cur === 0 ? 1 : cur === 1 ? "X" : 0;
      const copy = { ...c };
      if (next === 0) delete copy[idx]; else copy[idx] = next;
      return copy;
    });
  };
  const changeVars = (n) => {
    setNVars(n);
    const max = Math.pow(2, n);
    setCells((c) => Object.fromEntries(Object.entries(c).filter(([k]) => +k < max)));
  };
  // carry the current map over when switching to table mode
  const switchMode = (m) => {
    if (m === "table" && !err && result.n >= 2 && result.n <= 4) {
      const c = {};
      result.rows.forEach((row) => { if (row.out === 1 || row.out === "X") c[row.index] = row.out; });
      setNVars(result.n);
      setCells(c);
    }
    setMode(m);
  };

  const insertSym = (sym) => {
    const el = inputRef.current;
    if (!el) return;
    const start = el.selectionStart ?? expr.length;
    const end = el.selectionEnd ?? expr.length;
    const next = expr.slice(0, start) + sym + expr.slice(end);
    setExpr(next);
    requestAnimationFrame(() => {
      el.focus();
      el.selectionStart = el.selectionEnd = start + sym.length;
    });
  };

  const applyPreset = (key) => {
    setPreset(key);
    const p = BK_PRESETS[key];
    if (p.expr !== null) setExpr(p.expr);
  };

  // accent follows the module's home-card color
  const kBg = "#181512", kPanel = "#211c17", kGold = "#5EBF52", kGoldBright = "#a6dca0";
  const kTeal = "#86cf7d", kCream = "#f4efe4", kMuted = "#a89f8f", kLine = "#3a3327", kDanger = "#e8735a";

  const kPanelStyle = { background: kPanel, borderRadius: 20, padding: 18, margin: "14px 22px 0 22px" };
  const kKeyBtn = { fontFamily: "monospace", fontSize: 12, background: kBg, border: `1px solid ${kGold}40`, color: kCream, borderRadius: 7, padding: "7px 10px", cursor: "pointer" };
  const kOpKey = { ...kKeyBtn, color: kGoldBright, borderColor: `${kGold}66` };

  const layout = !err ? bkKmapLayout(result.n) : null;
  const outByIndex = {};
  if (!err) result.rows.forEach((r) => (outByIndex[r.index] = r.out));
  const piColor = new Map();
  if (!err) result.selected.forEach((pi, idx) => piColor.set(pi, BK_PI_COLORS[idx % BK_PI_COLORS.length]));
  const colLabel = !err ? (result.n === 1 ? result.vars[0] : layout.colBits === 2 ? result.vars.slice(layout.rowBits).join("") : result.vars[layout.rowBits] || "") : "";
  const rowLabel = !err ? (layout.rowBits === 0 ? "" : layout.rowBits === 2 ? result.vars.slice(0, 2).join("") : result.vars[0]) : "";

  return (
    <div className="screen-body">
      <div className="header">
        <div className="back neu" onClick={onBack} style={{ cursor: "pointer" }}>
          <BackIcon />
        </div>
        <div className="hlabel">MODULE &middot; KARNAUGH MAP</div>
      </div>

      <div style={{ ...kPanelStyle, color: kCream, fontFamily: "Inter, Arial, sans-serif" }}>
        <p style={{ fontFamily: "monospace", fontSize: 10, letterSpacing: "0.14em", textTransform: "uppercase", color: kTeal, margin: "0 0 6px" }}>MOD.04</p>
        <h2 style={{ fontWeight: 800, fontSize: 20, margin: "0 0 4px", fontFamily: "'Baloo 2',sans-serif" }}>
          Karnaugh <span style={{ color: kGoldBright }}>Map</span>
        </h2>
        <p style={{ color: kMuted, fontSize: 11.5, margin: "0 0 12px", lineHeight: 1.4 }}>
          Type an expression, build the circuit from gates, tap 1s into the table, or list minterms. It solves as you go.
        </p>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 4, background: kBg, borderRadius: 10, padding: 4, marginBottom: 14 }}>
          {[["expr", "Expression"], ["circuit", "Circuit"], ["table", "Table"], ["minterms", "Minterms"]].map(([k, label]) => (
            <button
              key={k}
              onClick={() => switchMode(k)}
              style={{
                border: "none", borderRadius: 7, padding: "8px 4px", cursor: "pointer", fontSize: 11.5, fontWeight: 700,
                background: mode === k ? kGold : "transparent", color: mode === k ? kBg : kCream,
              }}
            >
              {label}
            </button>
          ))}
        </div>

        {mode === "circuit" && (
          <>
            <div style={{ display: "flex", gap: 6, marginBottom: 10, flexWrap: "wrap" }}>
              <span style={{ fontSize: 11, color: kMuted, alignSelf: "center" }}>Start from</span>
              <button style={kKeyBtn} onClick={() => { setCircuit(ckExampleSOP()); setOutId(null); }}>AB + A'C</button>
              <button style={kKeyBtn} onClick={() => { setCircuit(ckExampleDecoder()); setOutId(null); }}>2-to-4 decoder</button>
              <button style={{ ...kKeyBtn, color: kDanger, borderColor: `${kDanger}66` }} onClick={() => { setCircuit({ nodes: [], wires: [] }); setOutId(null); }}>Blank</button>
            </div>
            <CircuitEditor
              nodes={circuit.nodes} setNodes={setCkNodes} wires={circuit.wires} setWires={setCkWires}
              levels={levels} setLevels={setLevels}
              colors={{ bg: kBg, line: kLine, gold: kGold, bright: kGoldBright, teal: kTeal, cream: kCream, muted: kMuted, danger: kDanger }}
            />
            {ck && !ck.err && ck.outputs.length > 1 && (
              <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 12, flexWrap: "wrap" }}>
                <span style={{ fontSize: 11, color: kMuted }}>Solve output</span>
                {ck.outputs.map((o) => {
                  const on = (result.circuitOut && result.circuitOut.id) === o.id;
                  return (
                    <button key={o.id} onClick={() => setOutId(o.id)}
                      style={{ ...kKeyBtn, padding: "6px 12px", background: on ? kGold : kBg, color: on ? kBg : kCream, fontWeight: 700 }}>
                      {o.label}
                    </button>
                  );
                })}
              </div>
            )}
            {ck && !ck.err && (
              <div style={{ marginTop: 12, fontSize: 11.5, color: kMuted, fontFamily: "monospace", lineHeight: 1.6, wordBreak: "break-word" }}>
                {ck.outputs.map((o) => (
                  <div key={o.id}><span style={{ color: kCream }}>{o.label}</span> = {ck.exprs[o.id]} <span style={{ opacity: 0.7 }}>(as wired)</span></div>
                ))}
              </div>
            )}
          </>
        )}

        {(mode === "table" || mode === "minterms") && (
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12 }}>
            <span style={{ fontSize: 11, color: kMuted }}>Variables</span>
            {[2, 3, 4].map((n) => (
              <button
                key={n}
                onClick={() => changeVars(n)}
                style={{ ...kKeyBtn, padding: "6px 12px", background: nVars === n ? kGold : kBg, color: nVars === n ? kBg : kCream, fontWeight: 700 }}
              >
                {n} <span style={{ fontWeight: 400, opacity: 0.75 }}>({["A", "B", "C", "D"].slice(0, n).join("")})</span>
              </button>
            ))}
          </div>
        )}

        {mode === "table" && (
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8 }}>
            <p style={{ fontSize: 11, color: kMuted, margin: 0, lineHeight: 1.4 }}>
              Tap a cell in the K-map below: 0 → 1 → X (don't care).
            </p>
            <button style={{ ...kKeyBtn, color: kDanger, borderColor: `${kDanger}66`, flex: "none" }} onClick={() => setCells({})}>Clear</button>
          </div>
        )}

        {mode === "minterms" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            <label style={{ fontSize: 11, color: kMuted }}>
              Minterms Σm( … )
              <input
                type="text" inputMode="numeric" spellCheck={false} value={mText} onChange={(e) => setMText(e.target.value)}
                placeholder="e.g. 0, 2, 5-7"
                style={{ display: "block", marginTop: 4, width: "100%", background: kBg, border: `1px solid ${kGold}4d`, color: kCream, fontFamily: "monospace", fontSize: 14, padding: "10px 12px", borderRadius: 9, outline: "none", boxSizing: "border-box" }}
              />
            </label>
            <label style={{ fontSize: 11, color: kMuted }}>
              Don't cares d( … ) — optional
              <input
                type="text" inputMode="numeric" spellCheck={false} value={dText} onChange={(e) => setDText(e.target.value)}
                placeholder="e.g. 3, 11"
                style={{ display: "block", marginTop: 4, width: "100%", background: kBg, border: `1px solid ${kGold}4d`, color: kCream, fontFamily: "monospace", fontSize: 14, padding: "10px 12px", borderRadius: 9, outline: "none", boxSizing: "border-box" }}
              />
            </label>
          </div>
        )}

        {mode !== "expr" && err && <div style={{ marginTop: 10, color: kDanger, fontSize: 12 }}>{err}</div>}

        {mode === "expr" && (<>
        <input
          ref={inputRef}
          type="text"
          spellCheck={false}
          value={expr}
          onChange={(e) => { setExpr(e.target.value); setPreset("custom"); }}
          style={{ width: "100%", background: kBg, border: `1px solid ${kGold}4d`, color: kCream, fontFamily: "monospace", fontSize: 14, padding: "10px 12px", borderRadius: 9, outline: "none", boxSizing: "border-box" }}
        />
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 12 }}>
          {["A", "B", "C", "D"].map((s) => (
            <button key={s} style={kKeyBtn} onClick={() => insertSym(s)}>{s}</button>
          ))}
          <button style={kOpKey} onClick={() => insertSym("¬")} title="NOT">NOT</button>
          <button style={kOpKey} onClick={() => insertSym("∧")} title="AND">AND</button>
          <button style={kOpKey} onClick={() => insertSym("∨")} title="OR">OR</button>
          <button style={kOpKey} onClick={() => insertSym("⊕")} title="XOR">XOR</button>
          <button style={kKeyBtn} onClick={() => insertSym("(")}>(</button>
          <button style={kKeyBtn} onClick={() => insertSym(")")}>)</button>
          <button style={{ ...kKeyBtn, color: kDanger, borderColor: `${kDanger}66` }} onClick={() => setExpr("")}>Clear</button>
        </div>
        {err && <div style={{ marginTop: 10, color: kDanger, fontSize: 12 }}>{err}</div>}

        <p style={{ fontSize: 10.5, color: kMuted, margin: "16px 0 6px" }}>Theorem presets</p>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 6 }}>
          {Object.entries(BK_PRESETS).map(([key, p]) => (
            <button
              key={key}
              onClick={() => applyPreset(key)}
              style={{
                fontFamily: "monospace", fontSize: 11, borderRadius: 7, padding: "8px 8px", cursor: "pointer",
                border: `1px solid ${preset === key ? kTeal : kGold + "40"}`,
                background: preset === key ? kTeal + "1f" : kBg,
                color: preset === key ? kTeal : kCream,
              }}
            >
              {p.label}
            </button>
          ))}
        </div>
        </>)}
      </div>

      {mode === "circuit" && ck && !ck.err && (
        <div style={kPanelStyle}>
          <p style={{ fontFamily: "monospace", fontSize: 10, color: kMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 8px" }}>Truth table</p>
          <div style={{ overflowX: "auto" }}>
            <table style={{ borderCollapse: "collapse", fontFamily: "monospace", fontSize: 12, margin: "0 auto" }}>
              <thead>
                <tr>
                  {ck.vars.map((v) => <th key={v} style={{ padding: "4px 9px", color: kMuted }}>{v}</th>)}
                  {ck.outputs.map((o) => <th key={o.id} style={{ padding: "4px 9px", color: kGoldBright, borderLeft: `1px solid ${kLine}` }}>{o.label}</th>)}
                </tr>
              </thead>
              <tbody>
                {ck.rows.map((row) => {
                  const live = ck.vars.every((v) => (levels[v] ? 1 : 0) === row.env[v]);
                  return (
                  <tr key={row.index} style={{ borderTop: `1px solid ${kLine}`, background: live ? kGold + "33" : "transparent", outline: live ? `1px solid ${kGold}` : "none" }}>
                    {ck.vars.map((v) => <td key={v} style={{ padding: "3px 9px", textAlign: "center", color: kCream }}>{row.env[v]}</td>)}
                    {ck.outputs.map((o) => (
                      <td key={o.id} style={{ padding: "3px 9px", textAlign: "center", fontWeight: 700, color: row.outs[o.id] ? kTeal : kMuted, borderLeft: `1px solid ${kLine}` }}>
                        {row.outs[o.id]}
                      </td>
                    ))}
                  </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          <p style={{ fontSize: 10.5, color: kMuted, margin: "8px 0 0", textAlign: "center" }}>Highlighted row = the input switches you set above.</p>
        </div>
      )}

      <div style={kPanelStyle}>
        <p style={{ fontFamily: "monospace", fontSize: 10, color: kMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 8px" }}>
          Minimized SOP{mode === "circuit" && result.circuitOut ? ` — ${result.circuitOut.label}` : ""}
        </p>
        <div style={{ fontSize: 18, fontWeight: 700, color: kGoldBright, fontFamily: "monospace", wordBreak: "break-word" }}>{err ? "—" : result.minimized}</div>
        <p style={{ fontFamily: "monospace", fontSize: 10, color: kMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: "14px 0 8px" }}>Minimized POS</p>
        <div style={{ fontSize: 18, fontWeight: 700, color: kTeal, fontFamily: "monospace", wordBreak: "break-word" }}>{err ? "—" : result.pos}</div>
        {!err && result.posSelected.length > 0 && (
          <p style={{ color: kMuted, fontSize: 11, margin: "6px 0 0", lineHeight: 1.4 }}>
            From grouping the 0-cells: {result.posSelected.map((pi) => "{" + pi.minterms.join(", ") + "}").join(" ")}
          </p>
        )}
        {!err && (
          <p style={{ color: kMuted, fontSize: 11, margin: "10px 0 0", fontFamily: "monospace", lineHeight: 1.5, wordBreak: "break-word" }}>
            {(result.circuitOut && result.circuitOut.label) || "F"} = Σm({result.minterms.join(", ") || "—"}){result.dontCares && result.dontCares.length ? ` + d(${result.dontCares.join(", ")})` : ""}
          </p>
        )}
      </div>

      <div style={{ ...kPanelStyle, marginBottom: 26 }}>
        <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 12px", fontFamily: "'Baloo 2',sans-serif", textAlign: "center", color: kCream }}>K-map grid</h3>
        {err ? (
          <div style={{ color: kMuted, fontSize: 12, textAlign: "center" }}>—</div>
        ) : !layout ? (
          <div style={{ color: kMuted, fontSize: 12, textAlign: "center" }}>K-map supports 1–4 variables. This expression uses {result.n}.</div>
        ) : (
          <>
            <div style={{ overflowX: "auto" }}>
              <table style={{ borderCollapse: "collapse", fontFamily: "monospace", fontSize: 11, margin: "0 auto" }}>
                <tbody>
                  <tr>
                    <th style={{ padding: 3, color: kMuted, fontSize: 9 }}>{rowLabel && colLabel ? `${rowLabel}\\${colLabel}` : ""}</th>
                    {layout.cols.map((c, i) => (
                      <th key={i} style={{ padding: 3, color: kMuted }}>{c || "—"}</th>
                    ))}
                  </tr>
                  {layout.rows.map((rBits, ri) => (
                    <tr key={ri}>
                      <th style={{ padding: 3, color: kMuted }}>{rBits || "—"}</th>
                      {layout.cols.map((cBits, ci) => {
                        const bits = rBits + cBits;
                        const idx = parseInt(bits, 2);
                        const isOn = outByIndex[idx] === 1;
                        const isDc = outByIndex[idx] === "X";
                        const editable = mode === "table";
                        const dots = result.selected.filter((pi) => pi.minterms.includes(idx));
                        return (
                          <td
                            key={ci}
                            onClick={editable ? () => cycleCell(idx) : undefined}
                            role={editable ? "button" : undefined}
                            aria-label={editable ? `Cell ${idx}, value ${isOn ? 1 : isDc ? "don't care" : 0}` : undefined}
                            style={{
                              border: `1px solid ${editable ? kGold + "66" : kLine}`, width: editable ? 50 : 38, height: editable ? 50 : 38,
                              textAlign: "center", position: "relative", cursor: editable ? "pointer" : "default", userSelect: "none",
                              background: isOn ? `${kTeal}24` : isDc ? `${kGold}14` : "transparent",
                              color: isOn ? kTeal : isDc ? kGoldBright : kMuted, fontWeight: isOn || isDc ? 700 : 400,
                              fontSize: editable ? 15 : 11,
                            }}
                          >
                            <div style={{ fontSize: 8, color: kMuted, position: "absolute", top: 2, left: 3 }}>{idx}</div>
                            <div>{isOn ? 1 : isDc ? "X" : 0}</div>
                            <div style={{ display: "flex", justifyContent: "center", gap: 2, position: "absolute", bottom: 2, left: 0, right: 0 }}>
                              {dots.map((pi, i) => (
                                <span key={i} style={{ width: 4, height: 4, borderRadius: "50%", background: piColor.get(pi), display: "inline-block" }} />
                              ))}
                            </div>
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {result.minterms.length === 0 ? (
              <p style={{ color: kMuted, fontSize: 12, marginTop: 10, textAlign: "center" }}>{mode === "table" ? "Tap cells to add 1s — groups appear here." : "No 1-cells to group."}</p>
            ) : (
              <div style={{ marginTop: 14 }}>
                {result.selected.map((pi, idx) => {
                  const color = piColor.get(pi);
                  const term = bkBitsToExpr(pi.bits, result.vars) || "1";
                  const dashCount = pi.bits.split("").filter((c) => c === "-").length;
                  const desc = dashCount === 0 ? "Single cell — no merge." : `{${pi.minterms.join(", ")}} — ${dashCount} variable${dashCount === 1 ? "" : "s"} dropped.`;
                  return (
                    <div key={idx} style={{ display: "flex", gap: 8, alignItems: "flex-start", fontSize: 11.5, marginBottom: 8 }}>
                      <span style={{ width: 10, height: 10, borderRadius: "50%", background: color, marginTop: 3, flex: "none" }} />
                      <div>
                        <span style={{ fontFamily: "monospace", color: kCream, fontWeight: 700, marginRight: 6 }}>{term}</span>
                        <span style={{ color: kMuted }}>{desc}</span>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

/* =========================================================
   Series & Parallel R — shared logic (ported from SeriesParallelR.jsx)
   ========================================================= */
const SR_PREC = { PARALLEL: 2, SERIES: 1 };

function srTokenize(raw) {
  const s = raw.replace(/\s+/g, "");
  const tokens = [];
  const re = /([0-9]*\.?[0-9]+)([kKmM]?)|([()+|])|(.)/g;
  let m;
  while ((m = re.exec(s))) {
    if (m[1] !== undefined) {
      let val = parseFloat(m[1]);
      const suf = m[2];
      if (suf === "k" || suf === "K") val *= 1e3;
      else if (suf === "M") val *= 1e6;
      else if (suf === "m") val *= 1e-3;
      if (val <= 0) throw new Error("Resistor values must be greater than 0.");
      tokens.push({ type: "NUM", value: val, label: m[1] + (suf || "") });
    } else if (m[3] !== undefined) {
      const c = m[3];
      if (c === "(") tokens.push({ type: "LP" });
      else if (c === ")") tokens.push({ type: "RP" });
      else if (c === "+") tokens.push({ type: "SERIES" });
      else if (c === "|") tokens.push({ type: "PARALLEL" });
    } else if (m[4] !== undefined) {
      throw new Error(`Unrecognized symbol "${m[4]}". Use numbers, + (series), | (parallel), and ( ).`);
    }
  }
  return tokens;
}

function srToRPN(tokens) {
  const output = [], ops = [];
  const isBin = (t) => t.type === "SERIES" || t.type === "PARALLEL";
  for (const tok of tokens) {
    if (tok.type === "NUM") output.push(tok);
    else if (isBin(tok)) {
      while (ops.length) {
        const top = ops[ops.length - 1];
        if (top.type === "LP") break;
        if (SR_PREC[top.type] >= SR_PREC[tok.type]) output.push(ops.pop());
        else break;
      }
      ops.push(tok);
    } else if (tok.type === "LP") ops.push(tok);
    else if (tok.type === "RP") {
      while (ops.length && ops[ops.length - 1].type !== "LP") output.push(ops.pop());
      if (!ops.length) throw new Error("Mismatched parentheses.");
      ops.pop();
    }
  }
  while (ops.length) {
    if (ops[ops.length - 1].type === "LP") throw new Error("Mismatched parentheses.");
    output.push(ops.pop());
  }
  return output;
}

function srEvalRPN(rpn, log) {
  const st = [];
  for (const tok of rpn) {
    if (tok.type === "NUM") st.push({ value: tok.value, label: tok.label + "Ω" });
    else {
      const b = st.pop(), a = st.pop();
      let value, sym;
      if (tok.type === "SERIES") { value = a.value + b.value; sym = "+"; }
      else { value = (a.value * b.value) / (a.value + b.value); sym = "∥"; }
      const label = fmtR(value) + "Ω";
      log.push(`${a.label} ${sym} ${b.label} = ${label}`);
      st.push({ value, label });
    }
  }
  if (st.length !== 1) throw new Error("Incomplete network.");
  return st[0];
}

/* network tree + schematic */
function srParseTree(tokens) {
  let pos = 0;
  const peek = () => tokens[pos];
  const next = () => tokens[pos++];
  function parseSeries() {
    const terms = [parseParallel()];
    while (peek() && peek().type === "SERIES") { next(); terms.push(parseParallel()); }
    return terms.length === 1 ? terms[0] : { type: "SERIES", children: terms };
  }
  function parseParallel() {
    const terms = [parseAtom()];
    while (peek() && peek().type === "PARALLEL") { next(); terms.push(parseAtom()); }
    return terms.length === 1 ? terms[0] : { type: "PARALLEL", children: terms };
  }
  function parseAtom() {
    const tok = peek();
    if (!tok) throw new Error("Unexpected end of expression.");
    if (tok.type === "NUM") { next(); return { type: "LEAF", value: tok.value, label: tok.label }; }
    if (tok.type === "LP") {
      next();
      const inner = parseSeries();
      const rp = next();
      if (!rp || rp.type !== "RP") throw new Error("Mismatched parentheses.");
      return inner;
    }
    throw new Error("Unexpected token in expression.");
  }
  const tree = parseSeries();
  if (pos !== tokens.length) throw new Error("Unexpected trailing tokens.");
  return tree;
}

function srSchemLeaf(node, unit) {
  const W = 64, CY = 18, BELOW = 22, H = CY + BELOW;
  const leadLen = 14, sx = leadLen, ex = W - leadLen;
  const symW = ex - sx, n = 6, dx = symW / n, amp = 6;
  let d = `M${sx},${CY}`;
  for (let i = 1; i <= n; i++) {
    const x = sx + dx * i;
    const y = i === n ? CY : CY + (i % 2 === 1 ? -amp : amp);
    d += ` L${x.toFixed(1)},${y}`;
  }
  const symbolSvg = `<line x1="0" y1="${CY}" x2="${sx}" y2="${CY}" stroke="#9a958c" stroke-width="1.3"/>`
    + `<path d="${d}" fill="none" stroke="#EBC826" stroke-width="1.6"/>`
    + `<line x1="${ex}" y1="${CY}" x2="${W}" y2="${CY}" stroke="#9a958c" stroke-width="1.3"/>`;
  const label = `<text x="${W / 2}" y="${CY + 14}" text-anchor="middle" font-family="monospace" font-size="8.5" fill="#a89f8f">${node.label}${unit}</text>`;
  return { w: W, h: H, cy: CY, svg: symbolSvg + label };
}

function srSchemSeries(children) {
  const GAP = 10;
  const topSpace = Math.max(...children.map((c) => c.cy));
  const botSpace = Math.max(...children.map((c) => c.h - c.cy));
  let x = 0;
  const parts = [];
  children.forEach((c, i) => {
    if (i > 0) { parts.push(`<line x1="${x}" y1="${topSpace}" x2="${x + GAP}" y2="${topSpace}" stroke="#9a958c" stroke-width="1.3"/>`); x += GAP; }
    const yOff = topSpace - c.cy;
    parts.push(`<g transform="translate(${x},${yOff})">${c.svg}</g>`);
    x += c.w;
  });
  return { w: x, h: topSpace + botSpace, cy: topSpace, svg: parts.join("") };
}

function srSchemParallel(children) {
  const GAP = 14;
  const maxW = Math.max(...children.map((c) => c.w));
  let y = 0;
  const parts = [], centers = [];
  children.forEach((c, i) => {
    if (i > 0) y += GAP;
    let branchSvg = c.svg;
    if (maxW > c.w) branchSvg += `<line x1="${c.w}" y1="${c.cy}" x2="${maxW}" y2="${c.cy}" stroke="#9a958c" stroke-width="1.3"/>`;
    parts.push(`<g transform="translate(0,${y})">${branchSvg}</g>`);
    centers.push(y + c.cy);
    y += c.h;
  });
  const top = centers[0], bot = centers[centers.length - 1];
  parts.push(`<line x1="0" y1="${top}" x2="0" y2="${bot}" stroke="#9a958c" stroke-width="1.3"/>`);
  parts.push(`<line x1="${maxW}" y1="${top}" x2="${maxW}" y2="${bot}" stroke="#9a958c" stroke-width="1.3"/>`);
  return { w: maxW, h: y, cy: (top + bot) / 2, svg: parts.join("") };
}

function srSchemLayout(node, unit) {
  if (node.type === "LEAF") return srSchemLeaf(node, unit);
  const childLayouts = node.children.map((c) => srSchemLayout(c, unit));
  return node.type === "SERIES" ? srSchemSeries(childLayouts) : srSchemParallel(childLayouts);
}

function srBuildSchematicSVG(tree, unit) {
  const root = srSchemLayout(tree, unit);
  const STUB = 18;
  const totalW = root.w + STUB * 2;
  const totalH = Math.max(root.h, 40);
  const leadIn = `<line x1="0" y1="${root.cy}" x2="${STUB}" y2="${root.cy}" stroke="#9a958c" stroke-width="1.3"/><circle cx="2" cy="${root.cy}" r="2.5" fill="#EBC826"/>`;
  const leadOut = `<line x1="${STUB + root.w}" y1="${root.cy}" x2="${totalW}" y2="${root.cy}" stroke="#9a958c" stroke-width="1.3"/><circle cx="${totalW - 2}" cy="${root.cy}" r="2.5" fill="#EBC826"/>`;
  const body = `<g transform="translate(${STUB},0)">${root.svg}</g>`;
  return { totalW, totalH, svg: `${leadIn}${body}${leadOut}` };
}

const SR_PRESETS = [
  { label: "Series ×3", expr: "100 + 220 + 470" },
  { label: "Parallel ×3", expr: "100 | 220 | 470" },
  { label: "Mixed ladder", expr: "100 + (220 | 470)" },
  { label: "kΩ values", expr: "(1k | 2.2k) + 330" },
];

/* =========================================================
   Series & Parallel R screen
   ========================================================= */
function SeriesParallelRScreen({ onBack }) {
  const [expr, setExpr] = useState("100 + (220 | 470)");

  const result = useMemo(() => {
    try {
      if (!expr.trim()) throw new Error("Enter a network expression.");
      const tokens = srTokenize(expr);
      if (!tokens.length) throw new Error("Enter a network expression.");
      const rpn = srToRPN(tokens);
      const log = [];
      const total = srEvalRPN(rpn, log);
      const tree = srParseTree(tokens);
      const schem = srBuildSchematicSVG(tree, "Ω");
      return { total, log, schem };
    } catch (e) {
      return { err: e.message };
    }
  }, [expr]);
  const err = result.err;

  // same dark "instrument module" palette used across modules
  // accent follows the module's home-card color
  const sBg = "#181512", sPanel = "#211c17", sGold = "#EBC826", sGoldBright = "#f4e188";
  const sTeal = "#f0d65c", sCream = "#f4efe4", sMuted = "#a89f8f", sLine = "#3a3327", sDanger = "#e8735a";
  const sPanelStyle = { background: sPanel, borderRadius: 20, padding: 18, margin: "14px 22px 0 22px" };

  return (
    <div className="screen-body">
      <div className="header">
        <div className="back neu" onClick={onBack} style={{ cursor: "pointer" }}>
          <BackIcon />
        </div>
        <div className="hlabel">MODULE &middot; SERIES &amp; PARALLEL R</div>
      </div>

      <div style={{ ...sPanelStyle, color: sCream, fontFamily: "Inter, Arial, sans-serif" }}>
        <p style={{ fontFamily: "monospace", fontSize: 10, letterSpacing: "0.14em", textTransform: "uppercase", color: sTeal, margin: "0 0 6px" }}>MOD.05</p>
        <h2 style={{ fontWeight: 800, fontSize: 20, margin: "0 0 4px", fontFamily: "'Baloo 2',sans-serif" }}>
          Series &amp; <span style={{ color: sGoldBright }}>Parallel R</span>
        </h2>
        <p style={{ color: sMuted, fontSize: 11.5, margin: "0 0 14px", lineHeight: 1.4 }}>
          Use + for series, | for parallel, ( ) to group. e.g. 100 + (220 | 470)
        </p>
        <input
          type="text"
          spellCheck={false}
          value={expr}
          onChange={(e) => setExpr(e.target.value)}
          style={{ width: "100%", background: sBg, border: `1px solid ${sGold}4d`, color: sCream, fontFamily: "monospace", fontSize: 14, padding: "10px 12px", borderRadius: 9, outline: "none", boxSizing: "border-box" }}
        />
        {err && <div style={{ marginTop: 10, color: sDanger, fontSize: 12 }}>{err}</div>}

        <p style={{ fontSize: 10.5, color: sMuted, margin: "16px 0 6px" }}>Quick examples</p>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 6 }}>
          {SR_PRESETS.map((p) => (
            <button
              key={p.label}
              onClick={() => setExpr(p.expr)}
              style={{ fontFamily: "monospace", fontSize: 11, background: sBg, border: `1px solid ${sGold}40`, color: sCream, borderRadius: 7, padding: "7px 8px", cursor: "pointer" }}
            >
              {p.label}
            </button>
          ))}
        </div>
      </div>

      <div style={sPanelStyle}>
        <p style={{ fontFamily: "monospace", fontSize: 10, color: sMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 8px" }}>Total resistance</p>
        <div style={{ fontSize: 19, fontWeight: 700, color: sGoldBright }}>{err ? "—" : `${fmtR(result.total.value)} Ω`}</div>
      </div>

      <div style={sPanelStyle}>
        <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 10px", fontFamily: "'Baloo 2',sans-serif" }}>Schematic</h3>
        {err || !result.schem ? (
          <div style={{ color: sMuted, fontSize: 12 }}>—</div>
        ) : (
          <div style={{ overflowX: "auto" }}>
            <svg viewBox={`0 0 ${result.schem.totalW} ${result.schem.totalH}`} width="100%" height={result.schem.totalH} dangerouslySetInnerHTML={{ __html: result.schem.svg }} />
          </div>
        )}
      </div>

      <div style={{ ...sPanelStyle, marginBottom: 26 }}>
        <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 10px", fontFamily: "'Baloo 2',sans-serif" }}>Reduction, group by group</h3>
        {err ? (
          <div style={{ color: sMuted, fontSize: 12 }}>—</div>
        ) : result.log.length === 0 ? (
          <div style={{ color: sMuted, fontSize: 12 }}>Single resistor — nothing to reduce.</div>
        ) : (
          result.log.map((s, i) => (
            <div key={i} style={{ fontFamily: "monospace", fontSize: 11.5, padding: "3px 0", color: sCream }}>{s}</div>
          ))
        )}
      </div>
    </div>
  );
}

/* =========================================================
   Voltage Divider — shared logic (ported from VoltageDivider.jsx)
   ========================================================= */
const VD_E24 = [1.0, 1.1, 1.2, 1.3, 1.5, 1.6, 1.8, 2.0, 2.2, 2.4, 2.7, 3.0, 3.3, 3.6, 3.9, 4.3, 4.7, 5.1, 5.6, 6.2, 6.8, 7.5, 8.2, 9.1];

function vdNearestE24(value) {
  if (!(value > 0)) return value;
  const exp = Math.floor(Math.log10(value));
  let best = null, bestDiff = Infinity;
  for (let e = exp - 1; e <= exp + 1; e++) {
    for (const m of VD_E24) {
      const cand = m * Math.pow(10, e);
      const diff = Math.abs(cand - value);
      if (diff < bestDiff) { bestDiff = diff; best = cand; }
    }
  }
  return best;
}

/* =========================================================
   Voltage Divider — recursive network model (series / parallel tree)
   ========================================================= */
function vdMakeLeaf(c, value = 10000) {
  return { id: "vd" + c.uid++, type: "R", value };
}

function vdMakeInitial() {
  const c = { uid: 1 };
  const root = { id: "vd" + c.uid++, type: "series", children: [vdMakeLeaf(c), vdMakeLeaf(c)] };
  return { root, counters: c };
}

/** Replace the node with the given id, via fn(node) -> newNode. Pure. */
function vdReplace(node, id, fn) {
  if (node.id === id) return fn(node);
  if (node.children) return { ...node, children: node.children.map((c) => vdReplace(c, id, fn)) };
  return node;
}

/** Remove a node by id; a block left with one child collapses into that child. Pure. */
function vdRemove(node, id) {
  if (!node.children) return node;
  const kept = node.children.filter((c) => c.id !== id).map((c) => vdRemove(c, id));
  if (kept.length === 1) return kept[0];
  return { ...node, children: kept };
}

/**
 * Add a branch next to the node with the given id.
 * If the node's own parent is already a block of this kind, the new leaf is
 * inserted as a sibling instead of nesting another block inside it. Pure.
 */
function vdWrapOrInsert(node, id, kind, leaf, mkId) {
  if (node.id === id) {
    if (node.children && node.type === kind) return { ...node, children: [...node.children, leaf] };
    return { id: mkId(), type: kind, children: [node, leaf] };
  }
  if (!node.children) return node;
  const idx = node.children.findIndex((c) => c.id === id);
  if (idx >= 0 && node.type === kind && node.children[idx].type !== kind) {
    const children = [...node.children];
    children.splice(idx + 1, 0, leaf);
    return { ...node, children };
  }
  return { ...node, children: node.children.map((c) => vdWrapOrInsert(c, id, kind, leaf, mkId)) };
}

function vdCountLeaves(node) {
  if (node.type === "R") return 1;
  return node.children.reduce((a, c) => a + vdCountLeaves(c), 0);
}

/**
 * Returns a decorated copy carrying _req on every node.
 * Series: Req = ΣR.  Parallel: Req = 1 / Σ(1/R).
 * A 0 Ω branch in parallel correctly shorts the block to 0 Ω (1/0 = ∞).
 */
function vdAnnotateReq(node) {
  if (node.type === "R") return { ...node, _req: node.value };
  const children = node.children.map(vdAnnotateReq);
  let req;
  if (node.type === "series") {
    req = children.reduce((a, c) => a + c._req, 0);
  } else {
    const sumInv = children.reduce((a, c) => a + 1 / c._req, 0);
    req = sumInv > 0 ? 1 / sumInv : 0;
  }
  return { ...node, children, _req: req };
}

/** Push voltage across / current through each node. Mutates the decorated copy. */
function vdPropagate(node, V, I) {
  node._V = V;
  node._I = I;
  if (!node.children) return;
  if (node.type === "series") {
    node.children.forEach((c) => vdPropagate(c, I * c._req, I));
  } else {
    node.children.forEach((c) => vdPropagate(c, V, c._req > 0 ? V / c._req : 0));
  }
}

/** Depth-first R1, R2, … labels for leaves; B1, B2, … for parallel blocks. Mutates. */
function vdLabel(node, c = { r: 1, b: 1 }) {
  if (node.type === "R") { node._label = "R" + c.r++; return c; }
  if (node.type === "parallel") node._label = "B" + c.b++;
  node.children.forEach((ch) => vdLabel(ch, c));
  return c;
}

function vdHasBadValue(node) {
  if (node.type === "R") return !isFinite(node.value) || node.value < 0;
  return node.children.some(vdHasBadValue);
}

/* =========================================================
   Shared: schematic zigzag resistor symbol (vertical)
   ========================================================= */
function SchematicResistorV({ x, y0, y1, stroke, strokeWidth = 2 }) {
  const segments = 6, amp = 9;
  const dy = (y1 - y0) / segments;
  const pts = [[x, y0]];
  for (let i = 1; i < segments; i++) {
    const y = y0 + dy * i;
    pts.push([x + (i % 2 === 1 ? amp : -amp), y]);
  }
  pts.push([x, y1]);
  return (
    <polyline
      points={pts.map((p) => p.join(",")).join(" ")}
      fill="none"
      stroke={stroke}
      strokeWidth={strokeWidth}
      strokeLinejoin="round"
      strokeLinecap="round"
    />
  );
}

/* =========================================================
   Voltage Divider — schematic layout for the series/parallel tree
   ========================================================= */
const VD_GAP_S = 30, VD_GAP_P = 24, VD_STUB = 20, VD_LEAF_W = 128, VD_LEAF_H = 52;

/** Assign _w/_h bottom-up. Mutates the decorated copy. */
function vdLayout(node) {
  if (node.type === "R") { node._w = VD_LEAF_W; node._h = VD_LEAF_H; return; }
  node.children.forEach(vdLayout);
  if (node.type === "series") {
    node._w = Math.max(...node.children.map((c) => c._w));
    node._h = node.children.reduce((a, c) => a + c._h, 0) + VD_GAP_S * (node.children.length - 1);
  } else {
    node._w = node.children.reduce((a, c) => a + c._w, 0) + VD_GAP_P * (node.children.length - 1);
    node._h = Math.max(...node.children.map((c) => c._h)) + VD_STUB * 2;
  }
}

function vdDraw(node, x, y, out, col) {
  const cx = x + node._w / 2;

  if (node.type === "R") {
    const midY = y + node._h / 2;
    out.push(
      <g key={node.id}>
        <SchematicResistorV x={cx} y0={y} y1={y + node._h} stroke={col.cream} />
        <text x={cx + 18} y={midY - 4} fontFamily="monospace" fontSize="9.5" fill={col.cream}>
          {node._label} = {fmtR(node.value)}Ω
        </text>
        <text x={cx + 18} y={midY + 8} fontFamily="monospace" fontSize="8.5" fill={col.teal}>
          {fmtR(node._V)}V · {fmtR(node._I * 1000)}mA
        </text>
      </g>
    );
    return;
  }

  if (node.type === "series") {
    let cy = y;
    node.children.forEach((c, i) => {
      if (i > 0) {
        out.push(<line key={`${node.id}-w${i}`} x1={cx} y1={cy} x2={cx} y2={cy + VD_GAP_S} stroke={col.gold} strokeWidth="2" />);
        cy += VD_GAP_S;
      }
      vdDraw(c, cx - c._w / 2, cy, out, col);
      cy += c._h;
    });
    return;
  }

  // parallel block: two rails with one column per branch
  const topRailY = y + VD_STUB;
  const botRailY = y + node._h - VD_STUB;
  const innerH = node._h - VD_STUB * 2;

  out.push(
    <g key={`${node.id}-box`}>
      <rect
        x={x - 7} y={y - 7} width={node._w + 14} height={node._h + 14}
        fill="none" stroke={col.gold} strokeWidth="1" strokeDasharray="4,4" rx="8" opacity="0.4"
      />
      <text x={x - 5} y={y - 11} fontFamily="monospace" fontSize="8.5" fill={col.gold} opacity="0.9">
        {node._label} ∥ {fmtR(node._req)}Ω
      </text>
      <line x1={cx} y1={y} x2={cx} y2={topRailY} stroke={col.gold} strokeWidth="2" />
      <line x1={cx} y1={botRailY} x2={cx} y2={y + node._h} stroke={col.gold} strokeWidth="2" />
      <line x1={x} y1={topRailY} x2={x + node._w} y2={topRailY} stroke={col.gold} strokeWidth="2" />
      <line x1={x} y1={botRailY} x2={x + node._w} y2={botRailY} stroke={col.gold} strokeWidth="2" />
      <circle cx={cx} cy={topRailY} r="3" fill={col.gold} />
      <circle cx={cx} cy={botRailY} r="3" fill={col.gold} />
    </g>
  );

  let cursor = x;
  node.children.forEach((c, i) => {
    const ccx = cursor + c._w / 2;
    const childY = topRailY + (innerH - c._h) / 2;
    out.push(
      <g key={`${node.id}-leg${i}`}>
        <line x1={ccx} y1={topRailY} x2={ccx} y2={childY} stroke={col.gold} strokeWidth="2" />
        <line x1={ccx} y1={childY + c._h} x2={ccx} y2={botRailY} stroke={col.gold} strokeWidth="2" />
      </g>
    );
    vdDraw(c, cursor, childY, out, col);
    cursor += c._w + VD_GAP_P;
  });
}

/**
 * Full schematic: Vin at the top, the network, GND at the bottom.
 * Tap labels sit at the junctions of the root series chain.
 */
/**
 * Battery symbol — same visual language as the old CircuitBuilder source,
 * recolored to the module's gold/teal/cream palette.
 */
function VDBattery({ x, yTop, yBot, vinLabel, gold, cream }) {
  const midY = (yTop + yBot) / 2;
  return (
    <g>
      <line x1={x} y1={yTop} x2={x} y2={midY - 20} stroke={gold} strokeWidth="2" />
      <line x1={x - 16} y1={midY - 20} x2={x + 16} y2={midY - 20} stroke={cream} strokeWidth="4" />
      <line x1={x - 8} y1={midY - 8} x2={x + 8} y2={midY - 8} stroke={cream} strokeWidth="2" />
      <line x1={x - 16} y1={midY + 8} x2={x + 16} y2={midY + 8} stroke={cream} strokeWidth="4" />
      <line x1={x - 8} y1={midY + 20} x2={x + 8} y2={midY + 20} stroke={cream} strokeWidth="2" />
      <line x1={x} y1={midY + 20} x2={x} y2={yBot} stroke={gold} strokeWidth="2" />
      <text x={x - 46} y={midY - 24} fontFamily="monospace" fontSize="13" fill={gold}>+</text>
      <text x={x - 62} y={midY + 5} fontFamily="monospace" fontSize="9.5" fill={cream} textAnchor="end">
        {vinLabel}
      </text>
    </g>
  );
}

/**
 * Full schematic: battery on the left, the network to its right, connected by
 * a top and bottom wire forming a closed loop — same orientation as the old
 * CircuitBuilder module. Tap labels sit at the junctions of the root series chain.
 */
function VoltageDividerNetworkSchematic({ tree, vinLabel, tapLabels, gold, teal, cream, muted }) {
  if (!tree) return null;

  const margin = 30, battX = 60, circX = battX + 64, padR = 96;
  const rootCx = circX + tree._w / 2;
  const netBottom = margin + tree._h;
  const W = circX + tree._w + padR;
  const H = Math.max(tree._h + margin * 2, 150);

  const parts = [];
  vdDraw(tree, circX, margin, parts, { gold, teal, cream, muted });

  // junction y-positions of the root series chain (only meaningful when root is series)
  const junctions = [];
  if (tree.type === "series") {
    let cy = margin;
    tree.children.forEach((c, i) => {
      if (i > 0) cy += VD_GAP_S;
      cy += c._h;
      if (i < tree.children.length - 1) junctions.push(cy + VD_GAP_S / 2);
    });
  }

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width="100%" style={{ display: "block" }}>
      <VDBattery x={battX} yTop={margin} yBot={netBottom} vinLabel={vinLabel} gold={gold} cream={cream} />

      <line x1={battX} y1={margin} x2={rootCx} y2={margin} stroke={gold} strokeWidth="2" />
      <line x1={battX} y1={netBottom} x2={rootCx} y2={netBottom} stroke={gold} strokeWidth="2" />
      <circle cx={rootCx} cy={margin} r="3.5" fill={gold} />
      <circle cx={rootCx} cy={netBottom} r="3.5" fill={gold} />

      {parts}

      {junctions.map((jy, i) => (
        <g key={`tap${i}`}>
          <circle cx={rootCx} cy={jy} r="3.5" fill={teal} />
          {tapLabels && tapLabels[i] != null && (
            <text x={rootCx - 10} y={jy + 4} fontFamily="monospace" fontSize="10" fill={teal} textAnchor="end">
              {tapLabels[i]}
            </text>
          )}
        </g>
      ))}
    </svg>
  );
}

/* =========================================================
   Voltage Divider — recursive tree editor row
   ========================================================= */
function VDTreeNode({ node, depth, onWrap, onRemove, onValueChange, canRemove, col }) {
  const isLeaf = node.type === "R";
  const tag = isLeaf ? "R" : node.type === "series" ? "series block" : "parallel block";

  const btn = {
    fontFamily: "monospace", fontSize: 9.5, borderRadius: 6, padding: "4px 7px",
    border: `1px solid ${col.gold}40`, background: col.bg, color: col.gold, cursor: "pointer",
  };

  return (
    <div style={{ borderLeft: `1px solid ${col.line}`, paddingLeft: 9, marginLeft: depth === 0 ? 0 : 3, marginTop: 6 }}>
      <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: 6 }}>
        <span style={{ fontFamily: "monospace", fontSize: 8.5, textTransform: "uppercase", letterSpacing: "0.05em", color: col.muted, minWidth: 54 }}>
          {tag}
        </span>

        {isLeaf && (
          <>
            <input
              type="number"
              step="any"
              min={0}
              value={node.value}
              onChange={(e) => onValueChange(node.id, e.target.value)}
              style={{
                width: 84, background: col.bg, border: `1px solid ${col.gold}4d`, color: col.cream,
                fontFamily: "monospace", fontSize: 11, padding: "5px 6px", borderRadius: 6, outline: "none",
              }}
            />
            <span style={{ fontSize: 10, color: col.muted }}>Ω</span>
          </>
        )}

        <button style={btn} onClick={() => onWrap(node.id, "series")} title="Put another resistor in series with this">
          + series ↓
        </button>
        <button style={{ ...btn, borderColor: col.teal + "59", color: col.teal }} onClick={() => onWrap(node.id, "parallel")} title="Put another resistor in parallel with this">
          + parallel ⇉
        </button>

        {canRemove && (
          <button
            style={{ ...btn, borderColor: col.danger + "59", color: col.danger }}
            onClick={() => onRemove(node.id)}
          >
            ✕
          </button>
        )}
      </div>

      {node.children &&
        node.children.map((c) => (
          <VDTreeNode
            key={c.id}
            node={c}
            depth={depth + 1}
            onWrap={onWrap}
            onRemove={onRemove}
            onValueChange={onValueChange}
            canRemove
            col={col}
          />
        ))}
    </div>
  );
}

/* =========================================================
   Voltage Divider screen
   ========================================================= */
function VoltageDividerScreen({ onBack }) {
  const [mode, setMode] = useState("forward"); // forward | reverse
  const [vin, setVin] = useState("5");
  const [net, setNet] = useState(() => vdMakeInitial()); // { root, counters }

  const [vinR, setVinR] = useState("9");
  const [voutTarget, setVoutTarget] = useState("3.3");
  const [fixWhich, setFixWhich] = useState("R1");
  const [fixedVal, setFixedVal] = useState("10000");

  const wrapNode = (id, kind) =>
    setNet((s) => {
      const c = { ...s.counters };
      const leaf = vdMakeLeaf(c);
      const root = vdWrapOrInsert(s.root, id, kind, leaf, () => "vd" + c.uid++);
      return { root, counters: c };
    });

  const removeNode = (id) =>
    setNet((s) => {
      if (id === s.root.id) return s;
      const root = vdRemove(s.root, id);
      // a divider needs at least two elements to have a node to tap
      if (vdCountLeaves(root) < 2) return s;
      return { ...s, root };
    });

  const setNodeValue = (id, raw) =>
    setNet((s) => ({ ...s, root: vdReplace(s.root, id, (n) => ({ ...n, value: raw === "" ? "" : parseFloat(raw) })) }));

  const result = useMemo(() => {
    if (mode === "forward") {
      const V = parseFloat(vin);
      if (isNaN(V)) return { err: "Enter a valid Vin." };
      if (vdHasBadValue(net.root)) return { err: "Enter valid, non-negative resistor values." };

      const tree = vdAnnotateReq(net.root);
      if (!(tree._req > 0)) return { err: "Total resistance must be more than 0 Ω." };

      const total = tree._req;
      const iTotal = V / total;
      vdPropagate(tree, V, iTotal);
      vdLabel(tree);
      vdLayout(tree);

      // taps: node voltage at each junction of the root series chain
      const taps = [];
      if (tree.type === "series") {
        let above = 0;
        for (let i = 0; i < tree.children.length - 1; i++) {
          above += tree.children[i]._req;
          const below = total - above;
          taps.push({ after: i + 1, below, vout: V * (below / total) });
        }
      }

      const steps = [];
      const hasParallel = JSON.stringify(net.root).includes('"parallel"');
      if (hasParallel) {
        steps.push("Each parallel block collapses first: R_eq = 1 / Σ(1/R)");
        const collapse = (n, path) => {
          if (n.type === "R") return;
          if (n.type === "parallel") {
            steps.push(`  ${n._label} = 1 / (${n.children.map((c) => `1/${fmtR(c._req)}`).join(" + ")}) = ${fmtR(n._req)} Ω`);
          }
          n.children.forEach((c) => collapse(c, path));
        };
        collapse(tree, "");
      }
      steps.push(`R_total = ${fmtR(total)} Ω`);
      steps.push(`I_total = Vin / R_total = ${V} / ${fmtR(total)} = ${fmtR(iTotal * 1000)} mA`);
      taps.forEach((t) => {
        steps.push(
          taps.length === 1
            ? `Vout = Vin × R_below / R_total = ${V} × ${fmtR(t.below)} / ${fmtR(total)} = ${fmtR(t.vout)} V`
            : `Node after element ${t.after}: Vout = ${V} × ${fmtR(t.below)} / ${fmtR(total)} = ${fmtR(t.vout)} V`
        );
      });

      return { tree, total, iTotal, taps, steps };
    }

    const V = parseFloat(vinR), target = parseFloat(voutTarget), fixed = parseFloat(fixedVal);
    if (isNaN(V) || isNaN(target) || isNaN(fixed) || fixed <= 0) return { err: "Enter valid values." };
    if (!(target > 0 && target < V)) return { err: "Target Vout must be between 0 and Vin." };
    const k = target / V;
    let exactOther, otherLabel, fixedLabel;
    if (fixWhich === "R1") { exactOther = (fixed * k) / (1 - k); fixedLabel = "R1"; otherLabel = "R2"; }
    else { exactOther = (fixed * (1 - k)) / k; fixedLabel = "R2"; otherLabel = "R1"; }
    const suggested = vdNearestE24(exactOther);
    const r1final = fixWhich === "R1" ? fixed : suggested;
    const r2final = fixWhich === "R1" ? suggested : fixed;
    const achievedVout = V * (r2final / (r1final + r2final));
    const errPct = (Math.abs(achievedVout - target) / target) * 100;
    const steps = [
      `k = Vout / Vin = ${target} / ${V} = ${fmtR(k)}`,
      fixWhich === "R1"
        ? `R2 = R1 × k / (1−k) = ${fixed} × ${fmtR(k)} / ${fmtR(1 - k)} = ${fmtR(exactOther)} Ω exact`
        : `R1 = R2 × (1−k) / k = ${fixed} × ${fmtR(1 - k)} / ${fmtR(k)} = ${fmtR(exactOther)} Ω exact`,
      `Nearest E24 value: ${fmtR(suggested)} Ω`,
      `Achieved Vout: ${fmtR(achievedVout)} V (${errPct.toFixed(2)}% off target)`,
    ];
    return { fixed, fixedLabel, suggested, otherLabel, achievedVout, steps };
  }, [mode, vin, net, vinR, voutTarget, fixWhich, fixedVal]);

  const schematic = useMemo(() => {
    if (result.err) return null;
    if (mode === "forward") {
      return {
        tree: result.tree,
        tapLabels: result.taps.map((t) => `${fmtR(t.vout)} V`),
        vinLabel: `Vin = ${fmtR(parseFloat(vin))} V`,
      };
    }
    const r1 = fixWhich === "R1" ? result.fixed : result.suggested;
    const r2 = fixWhich === "R1" ? result.suggested : result.fixed;
    const c = { uid: 1 };
    const plain = {
      id: "rv0", type: "series",
      children: [{ id: "rv1", type: "R", value: r1 }, { id: "rv2", type: "R", value: r2 }],
    };
    const tree = vdAnnotateReq(plain);
    vdPropagate(tree, parseFloat(vinR), tree._req > 0 ? parseFloat(vinR) / tree._req : 0);
    vdLabel(tree);
    vdLayout(tree);
    return { tree, tapLabels: [`${fmtR(result.achievedVout)} V`], vinLabel: `Vin = ${fmtR(parseFloat(vinR))} V` };
  }, [mode, vin, vinR, fixWhich, result]);

  // same dark "instrument module" palette used across modules
  // accent follows the module's home-card color
  const vBg = "#181512", vPanel = "#211c17", vGold = "#F26558", vGoldBright = "#f8aaa3";
  const vTeal = "#f58c82", vCream = "#f4efe4", vMuted = "#a89f8f", vLine = "#3a3327", vDanger = "#e8735a";
  const vPanelStyle = { background: vPanel, borderRadius: 20, padding: 18, margin: "14px 22px 0 22px" };
  const vInputStyle = { width: "100%", background: vBg, border: `1px solid ${vGold}4d`, color: vCream, fontFamily: "monospace", fontSize: 13, padding: "8px 9px", borderRadius: 8, outline: "none", boxSizing: "border-box" };
  const vLabelStyle = { display: "block", fontSize: 9.5, color: vMuted, marginBottom: 4, textTransform: "uppercase", letterSpacing: "0.05em" };
  const vModeBtn = (active) => ({
    fontFamily: "monospace", fontSize: 11.5, borderRadius: 7, padding: "9px 10px", cursor: "pointer",
    border: `1px solid ${active ? vTeal : vGold + "40"}`, background: active ? vTeal + "1f" : vBg, color: active ? vTeal : vCream,
  });
  const treeCol = { bg: vBg, gold: vGold, teal: vTeal, cream: vCream, muted: vMuted, line: vLine, danger: vDanger };

  return (
    <div className="screen-body">
      <div className="header">
        <div className="back neu" onClick={onBack} style={{ cursor: "pointer" }}>
          <BackIcon />
        </div>
        <div className="hlabel">MODULE &middot; VOLTAGE DIVIDER</div>
      </div>

      <div style={{ ...vPanelStyle, color: vCream, fontFamily: "Inter, Arial, sans-serif" }}>
        <p style={{ fontFamily: "monospace", fontSize: 10, letterSpacing: "0.14em", textTransform: "uppercase", color: vTeal, margin: "0 0 6px" }}>MOD.06</p>
        <h2 style={{ fontWeight: 800, fontSize: 20, margin: "0 0 4px", fontFamily: "'Baloo 2',sans-serif" }}>
          Voltage <span style={{ color: vGoldBright }}>Divider</span>
        </h2>
        <p style={{ color: vMuted, fontSize: 11.5, margin: "0 0 14px", lineHeight: 1.4 }}>
          Build a series/parallel network and solve Vout, or pick a resistor you have and get the standard value to pair it with.
        </p>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 14 }}>
          <button style={vModeBtn(mode === "forward")} onClick={() => setMode("forward")}>Solve Vout</button>
          <button style={vModeBtn(mode === "reverse")} onClick={() => setMode("reverse")}>Solve resistors</button>
        </div>

        {mode === "forward" ? (
          <div>
            <label style={vLabelStyle}>Vin</label>
            <input type="number" step="any" value={vin} onChange={(e) => setVin(e.target.value)} style={vInputStyle} />

            <p style={{ fontSize: 10.5, color: vMuted, margin: "14px 0 2px" }}>Network (Vin to GND)</p>
            <div style={{ maxHeight: 220, overflowY: "auto", paddingRight: 2 }}>
              <VDTreeNode
                node={net.root}
                depth={0}
                onWrap={wrapNode}
                onRemove={removeNode}
                onValueChange={setNodeValue}
                canRemove={false}
                col={treeCol}
              />
            </div>
            <p style={{ color: vMuted, fontSize: 10.5, marginTop: 10, lineHeight: 1.4 }}>
              “+ series” drops a resistor below this one; “+ parallel” puts one beside it. Vout is reported at every node of
              the outermost series chain.
            </p>
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
              <div>
                <label style={vLabelStyle}>Vin</label>
                <input type="number" step="any" value={vinR} onChange={(e) => setVinR(e.target.value)} style={vInputStyle} />
              </div>
              <div>
                <label style={vLabelStyle}>Target Vout</label>
                <input type="number" step="any" value={voutTarget} onChange={(e) => setVoutTarget(e.target.value)} style={vInputStyle} />
              </div>
            </div>
            <div>
              <label style={vLabelStyle}>I already have</label>
              <select value={fixWhich} onChange={(e) => setFixWhich(e.target.value)} style={vInputStyle}>
                <option value="R1">R1 (top, to Vin)</option>
                <option value="R2">R2 (bottom, to GND)</option>
              </select>
            </div>
            <div>
              <label style={vLabelStyle}>Its value (Ω)</label>
              <input type="number" step="any" value={fixedVal} onChange={(e) => setFixedVal(e.target.value)} style={vInputStyle} />
            </div>
          </div>
        )}
        {result.err && <div style={{ marginTop: 10, color: vDanger, fontSize: 12 }}>{result.err}</div>}
      </div>

      {schematic && (
        <div style={{ ...vPanelStyle, overflowX: "auto" }}>
          <p style={{ fontFamily: "monospace", fontSize: 10, color: vMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 10px" }}>
            Circuit
          </p>
          <VoltageDividerNetworkSchematic
            tree={schematic.tree}
            tapLabels={schematic.tapLabels}
            vinLabel={schematic.vinLabel}
            gold={vGold}
            teal={vTeal}
            cream={vCream}
            muted={vMuted}
          />
        </div>
      )}

      {mode === "forward" && !result.err && (
        <div style={vPanelStyle}>
          <p style={{ fontFamily: "monospace", fontSize: 10, color: vMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 10px" }}>
            Network totals
          </p>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            <div style={{ textAlign: "center" }}>
              <div style={{ fontFamily: "monospace", fontWeight: 700, fontSize: 15, color: vGoldBright }}>{fmtR(result.total)}Ω</div>
              <div style={{ fontFamily: "monospace", fontSize: 9, color: vMuted, marginTop: 4, textTransform: "uppercase" }}>R total</div>
            </div>
            <div style={{ textAlign: "center" }}>
              <div style={{ fontFamily: "monospace", fontWeight: 700, fontSize: 15, color: vTeal }}>{fmtR(result.iTotal * 1000)} mA</div>
              <div style={{ fontFamily: "monospace", fontSize: 9, color: vMuted, marginTop: 4, textTransform: "uppercase" }}>I total</div>
            </div>
          </div>
        </div>
      )}

      <div style={vPanelStyle}>
        <p style={{ fontFamily: "monospace", fontSize: 10, color: vMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 10px" }}>
          {mode === "forward" ? (result.taps && result.taps.length > 1 ? "Vout at each tap" : "Vout") : "Suggested resistors"}
        </p>
        {result.err ? (
          <div style={{ color: vMuted, fontSize: 12 }}>—</div>
        ) : mode === "forward" ? (
          result.taps.length === 0 ? (
            <div style={{ color: vMuted, fontSize: 11.5, lineHeight: 1.4 }}>
              The whole network is one parallel block, so there is no intermediate node to tap. Add a series element to create one.
            </div>
          ) : result.taps.length === 1 ? (
            <div style={{ fontSize: 19, fontWeight: 700, color: vGoldBright }}>{fmtR(result.taps[0].vout)} V</div>
          ) : (
            <div style={{ display: "grid", gridTemplateColumns: `repeat(${Math.min(result.taps.length, 3)}, 1fr)`, gap: 10 }}>
              {result.taps.map((t, i) => (
                <div key={i} style={{ textAlign: "center" }}>
                  <div style={{ fontFamily: "monospace", fontWeight: 700, fontSize: 15, color: vGoldBright }}>{fmtR(t.vout)} V</div>
                  <div style={{ fontFamily: "monospace", fontSize: 9, color: vMuted, marginTop: 4, textTransform: "uppercase" }}>node {t.after}</div>
                </div>
              ))}
            </div>
          )
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            <div style={{ textAlign: "center" }}>
              <div style={{ fontFamily: "monospace", fontWeight: 700, fontSize: 15, color: vGoldBright }}>{fmtR(result.fixed)}Ω</div>
              <div style={{ fontFamily: "monospace", fontSize: 9, color: vMuted, marginTop: 4, textTransform: "uppercase" }}>{result.fixedLabel} · fixed</div>
            </div>
            <div style={{ textAlign: "center" }}>
              <div style={{ fontFamily: "monospace", fontWeight: 700, fontSize: 15, color: vTeal }}>{fmtR(result.suggested)}Ω</div>
              <div style={{ fontFamily: "monospace", fontSize: 9, color: vMuted, marginTop: 4, textTransform: "uppercase" }}>{result.otherLabel} · E24 suggestion</div>
            </div>
          </div>
        )}
      </div>

      <div style={vPanelStyle}>
        <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 10px", fontFamily: "'Baloo 2',sans-serif" }}>Steps</h3>
        {result.err ? (
          <div style={{ color: vMuted, fontSize: 12 }}>—</div>
        ) : (
          result.steps.map((s, i) => (
            <div key={i} style={{ fontFamily: "monospace", fontSize: 11.5, padding: "3px 0", color: vCream, whiteSpace: "pre-wrap" }}>{s}</div>
          ))
        )}
      </div>

      <div style={{ ...vPanelStyle, marginBottom: 26 }}>
        <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 10px", fontFamily: "'Baloo 2',sans-serif" }}>Formula reference</h3>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 11 }}>
          <tbody>
            {[
              ["Series", "R_eq = R1 + R2 + …"],
              ["Parallel", "R_eq = 1 / (1/R1 + 1/R2 + …)"],
              ["Vout", "Vin · R_below / R_total"],
              ["R2 (R1 known)", "R1 · k/(1−k)"],
              ["R1 (R2 known)", "R2 · (1−k)/k"],
              ["k", "Vout / Vin"],
            ].map(([name, formula]) => (
              <tr key={name} style={{ borderTop: `1px solid ${vLine}` }}>
                <td style={{ padding: "6px 4px", color: vGold, fontWeight: 700 }}>{name}</td>
                <td style={{ padding: "6px 4px", fontFamily: "monospace", color: vMuted }}>{formula}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* =========================================================
   Series & Parallel L/C — shared logic (ported from CalculatorModules.jsx)
   ========================================================= */
function lcFmtSI(n) {
  if (!isFinite(n)) return "—";
  const abs = Math.abs(n);
  const tiers = [
    [1e6, "M"], [1e3, "k"], [1, ""], [1e-3, "m"],
    [1e-6, "µ"], [1e-9, "n"], [1e-12, "p"],
  ];
  for (const [f, unit] of tiers) {
    if (abs >= f || f === 1e-12) return parseFloat((n / f).toFixed(4)).toString() + unit;
  }
  return n.toString();
}

const LC_PREC = { PARALLEL: 2, SERIES: 1 };

function lcTokenize(raw) {
  const s = raw.replace(/\s+/g, "");
  const tokens = [];
  const re = /([0-9]*\.?[0-9]+)(p|n|u|µ|m|k|M)?|([()+|])|(.)/g;
  let m;
  while ((m = re.exec(s))) {
    if (m[0] === "") continue;
    if (m[1] !== undefined) {
      let val = parseFloat(m[1]);
      const suf = m[2];
      const mult = { p: 1e-12, n: 1e-9, u: 1e-6, "µ": 1e-6, m: 1e-3, k: 1e3, M: 1e6 }[suf] || 1;
      val *= mult;
      if (val <= 0) throw new Error("Values must be greater than 0.");
      tokens.push({ type: "NUM", value: val, label: m[1] + (suf || "") });
    } else if (m[3] !== undefined) {
      const c = m[3];
      if (c === "(") tokens.push({ type: "LP" });
      else if (c === ")") tokens.push({ type: "RP" });
      else if (c === "+") tokens.push({ type: "SERIES" });
      else if (c === "|") tokens.push({ type: "PARALLEL" });
    } else if (m[4] !== undefined) {
      throw new Error(`Unrecognized symbol "${m[4]}". Use numbers, + (series), | (parallel), and ( ).`);
    }
  }
  return tokens;
}

function lcToRPN(tokens) {
  const output = [], ops = [];
  const isBin = (t) => t.type === "SERIES" || t.type === "PARALLEL";
  for (const tok of tokens) {
    if (tok.type === "NUM") output.push(tok);
    else if (isBin(tok)) {
      while (ops.length) {
        const top = ops[ops.length - 1];
        if (top.type === "LP") break;
        if (LC_PREC[top.type] >= LC_PREC[tok.type]) output.push(ops.pop());
        else break;
      }
      ops.push(tok);
    } else if (tok.type === "LP") { ops.push(tok); }
    else if (tok.type === "RP") {
      while (ops.length && ops[ops.length - 1].type !== "LP") output.push(ops.pop());
      if (!ops.length) throw new Error("Mismatched parentheses.");
      ops.pop();
    }
  }
  while (ops.length) {
    if (ops[ops.length - 1].type === "LP") throw new Error("Mismatched parentheses.");
    output.push(ops.pop());
  }
  return output;
}

function lcEvalRPN(rpn, log, componentType) {
  const unit = componentType === "capacitor" ? "F" : "H";
  // Series adds directly for everything except capacitors (reciprocal in series).
  // Parallel adds directly only for capacitors (reciprocal in parallel otherwise).
  const seriesAdds = componentType !== "capacitor";
  const parallelAdds = componentType === "capacitor";
  const st = [];
  for (const tok of rpn) {
    if (tok.type === "NUM") { st.push({ value: tok.value, label: tok.label + unit }); }
    else {
      const b = st.pop(), a = st.pop();
      const additive = tok.type === "SERIES" ? seriesAdds : parallelAdds;
      let value, sym;
      if (additive) { value = a.value + b.value; sym = "+"; }
      else { value = (a.value * b.value) / (a.value + b.value); sym = "∥"; }
      const label = lcFmtSI(value) + unit;
      log.push(`${a.label} ${sym} ${b.label} = ${label}`);
      st.push({ value, label });
    }
  }
  if (st.length !== 1) throw new Error("Incomplete network.");
  return st[0];
}

/* =========================================================
   Current Divider — shared logic (ported from CalculatorModules.jsx)
   ========================================================= */
function cdFmtPlain(n) {
  if (!isFinite(n)) return "—";
  const abs = Math.abs(n);
  if (abs !== 0 && (abs < 0.001 || abs >= 100000)) return n.toExponential(3);
  return parseFloat(n.toFixed(4)).toString();
}

/* =========================================================
   Series & Parallel L/C screen
   ========================================================= */
const LC_PRESETS = (u) => [
  { label: "Series ×3", expr: `10${u} + 22${u} + 47${u}` },
  { label: "Parallel ×3", expr: `10${u} | 22${u} | 47${u}` },
];

function SeriesParallelLCScreen({ onBack }) {
  const [componentType, setComponentType] = useState("inductor"); // inductor | capacitor
  const [expr, setExpr] = useState("10m + (22m | 47m)");

  const isCap = componentType === "capacitor";
  const sym = isCap ? "C" : "L";

  const result = useMemo(() => {
    try {
      if (!expr.trim()) throw new Error("Enter a network expression.");
      const tokens = lcTokenize(expr);
      if (!tokens.length) throw new Error("Enter a network expression.");
      const rpn = lcToRPN(tokens);
      const log = [];
      const total = lcEvalRPN(rpn, log, componentType);
      return { total, log: log.length ? log : ["Single component — nothing to reduce."] };
    } catch (e) {
      return { err: e.message };
    }
  }, [expr, componentType]);
  const err = result.err;

  const seriesFormula = isCap ? `1/${sym} = 1/${sym}1+1/${sym}2+...` : `${sym} = ${sym}1+${sym}2+...`;
  const parallelFormula = isCap ? `${sym} = ${sym}1+${sym}2+...` : `1/${sym} = 1/${sym}1+1/${sym}2+...`;

  // same dark "instrument module" palette used across modules
  // accent follows the module's home-card color
  const lBg = "#181512", lPanel = "#211c17", lGold = "#2FB89A", lGoldBright = "#8dd8c7";
  const lTeal = "#63cab3", lCream = "#f4efe4", lMuted = "#a89f8f", lLine = "#3a3327", lDanger = "#e8735a";
  const lPanelStyle = { background: lPanel, borderRadius: 20, padding: 18, margin: "14px 22px 0 22px" };
  const lChip = (active) => ({
    fontFamily: "monospace", fontSize: 11.5, borderRadius: 999, padding: "8px 14px", cursor: "pointer",
    border: `1px solid ${active ? lTeal : lGold + "40"}`, background: active ? lTeal : lBg, color: active ? lBg : lCream, fontWeight: active ? 700 : 400,
  });

  return (
    <div className="screen-body">
      <div className="header">
        <div className="back neu" onClick={onBack} style={{ cursor: "pointer" }}>
          <BackIcon />
        </div>
        <div className="hlabel">MODULE &middot; SERIES &amp; PARALLEL L/C</div>
      </div>

      <div style={{ ...lPanelStyle, color: lCream, fontFamily: "Inter, Arial, sans-serif" }}>
        <p style={{ fontFamily: "monospace", fontSize: 10, letterSpacing: "0.14em", textTransform: "uppercase", color: lTeal, margin: "0 0 6px" }}>MOD.07</p>
        <h2 style={{ fontWeight: 800, fontSize: 20, margin: "0 0 4px", fontFamily: "'Baloo 2',sans-serif" }}>
          Series &amp; Parallel <span style={{ color: lGoldBright }}>L/C</span>
        </h2>
        <p style={{ color: lMuted, fontSize: 11.5, margin: "0 0 14px", lineHeight: 1.4 }}>
          Use + for series, | for parallel, ( ) to group. Suffixes: p n u m k (u = µ). e.g. 10m + (22m | 47m)
        </p>

        <p style={{ fontSize: 10.5, color: lMuted, margin: "0 0 6px" }}>Component type</p>
        <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
          <button style={lChip(!isCap)} onClick={() => { setComponentType("inductor"); setExpr("10m + (22m | 47m)"); }}>Inductor</button>
          <button style={lChip(isCap)} onClick={() => { setComponentType("capacitor"); setExpr("10u + (22u | 47u)"); }}>Capacitor</button>
        </div>

        <p style={{ fontSize: 10.5, color: lMuted, margin: "0 0 6px" }}>Network expression</p>
        <input
          type="text"
          spellCheck={false}
          value={expr}
          onChange={(e) => setExpr(e.target.value)}
          style={{ width: "100%", background: lBg, border: `1px solid ${lGold}4d`, color: lCream, fontFamily: "monospace", fontSize: 14, padding: "10px 12px", borderRadius: 9, outline: "none", boxSizing: "border-box" }}
        />
        <div style={{ display: "flex", gap: 8, marginTop: 10, flexWrap: "wrap" }}>
          {LC_PRESETS(isCap ? "u" : "m").map((p) => (
            <button key={p.label} style={lChip(false)} onClick={() => setExpr(p.expr)}>{p.label}</button>
          ))}
        </div>
        {err && <div style={{ marginTop: 10, color: lDanger, fontSize: 12 }}>{err}</div>}
      </div>

      <div style={lPanelStyle}>
        <p style={{ fontFamily: "monospace", fontSize: 10, color: lMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 8px" }}>
          Total {isCap ? "capacitance" : "inductance"}
        </p>
        <div style={{ fontSize: 19, fontWeight: 700, color: lGoldBright }}>{err ? "—" : `${lcFmtSI(result.total.value)}${isCap ? "F" : "H"}`}</div>
      </div>

      <div style={lPanelStyle}>
        <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 10px", fontFamily: "'Baloo 2',sans-serif" }}>Steps</h3>
        {err ? (
          <div style={{ color: lMuted, fontSize: 12 }}>—</div>
        ) : (
          result.log.map((s, i) => (
            <div key={i} style={{ fontFamily: "monospace", fontSize: 11.5, padding: "3px 0", color: lCream }}>{s}</div>
          ))
        )}
      </div>

      <div style={{ ...lPanelStyle, marginBottom: 26 }}>
        <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 10px", fontFamily: "'Baloo 2',sans-serif" }}>Formula reference</h3>
        {[["Series", seriesFormula], ["Parallel", parallelFormula]].map(([name, formula]) => (
          <div key={name} style={{ borderTop: `1px solid ${lLine}`, display: "flex", justifyContent: "space-between", gap: 10, padding: "8px 0" }}>
            <span style={{ color: lGold, fontWeight: 600, fontSize: 12 }}>{name}</span>
            <span style={{ fontFamily: "monospace", color: lCream, fontSize: 12, textAlign: "right" }}>{formula}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

/* =========================================================
   Current Divider screen
   ========================================================= */
function CurrentDividerScreen({ onBack }) {
  const [mode, setMode] = useState("voltage"); // voltage | current
  const [source, setSource] = useState("100");
  const [resistors, setResistors] = useState(["10", "25", "100"]);

  const addRow = () => setResistors((prev) => [...prev, "100"]);
  const removeRow = (idx) => setResistors((prev) => (prev.length <= 2 ? prev : prev.filter((_, i) => i !== idx)));
  const updateRow = (idx, val) => setResistors((prev) => prev.map((r, i) => (i === idx ? val : r)));

  const result = useMemo(() => {
    const Rs = resistors.map((r) => parseFloat(r));
    if (Rs.length < 2 || Rs.some((r) => isNaN(r) || r <= 0)) {
      return { error: "Enter at least two positive resistor values." };
    }
    const src = parseFloat(source);
    if (isNaN(src) || src <= 0) {
      return { error: mode === "voltage" ? "Enter a valid Vs." : "Enter a valid I_T." };
    }

    const Gs = Rs.map((r) => 1 / r);
    const Gt = Gs.reduce((a, b) => a + b, 0);
    const Req = 1 / Gt;
    const log = [`R_EQ = 1 / (${Rs.map((_, i) => `1/R${i + 1}`).join(" + ")}) = ${cdFmtPlain(Req)} Ω`];

    let branches, headline, headlineLbl;
    if (mode === "voltage") {
      branches = Rs.map((r) => src / r);
      const IT = branches.reduce((a, b) => a + b, 0);
      headline = `${cdFmtPlain(IT)} A`;
      headlineLbl = "Total current I_T";
      Rs.forEach((r, i) => log.push(`I_R${i + 1} = Vs / R${i + 1} = ${cdFmtPlain(src)} / ${cdFmtPlain(r)} = ${cdFmtPlain(branches[i])} A`));
      log.push(`I_T = ΣI_Rn = ${cdFmtPlain(IT)} A`);
    } else {
      branches = Rs.map((r) => src * (Req / r));
      headline = `${cdFmtPlain(Req)} Ω`;
      headlineLbl = "Equivalent resistance R_EQ";
      Rs.forEach((r, i) => log.push(`I_R${i + 1} = I_T × (R_EQ/R${i + 1}) = ${cdFmtPlain(src)} × (${cdFmtPlain(Req)}/${cdFmtPlain(r)}) = ${cdFmtPlain(branches[i])} A`));
      const check = branches.reduce((a, b) => a + b, 0);
      log.push(`Check: ΣI_Rn = ${cdFmtPlain(check)} A (should equal I_T = ${cdFmtPlain(src)} A)`);
    }

    return { Rs, branches, headline, headlineLbl, log };
  }, [resistors, source, mode]);

  // same dark "instrument module" palette used across modules
  // accent follows the module's home-card color
  const dBg = "#181512", dPanel = "#211c17", dGold = "#4FA8DE", dGoldBright = "#9ecfed";
  const dTeal = "#7bbee6", dCream = "#f4efe4", dMuted = "#a89f8f", dLine = "#3a3327", dDanger = "#e8735a";
  const dPanelStyle = { background: dPanel, borderRadius: 20, padding: 18, margin: "14px 22px 0 22px" };
  const dChip = (active) => ({
    fontFamily: "monospace", fontSize: 11.5, borderRadius: 999, padding: "8px 14px", cursor: "pointer",
    border: `1px solid ${active ? dTeal : dGold + "40"}`, background: active ? dTeal : dBg, color: active ? dBg : dCream, fontWeight: active ? 700 : 400,
  });
  const dInputStyle = { width: "100%", background: dBg, border: `1px solid ${dGold}4d`, color: dCream, fontFamily: "monospace", fontSize: 13, padding: "9px 11px", borderRadius: 8, outline: "none", boxSizing: "border-box" };

  return (
    <div className="screen-body">
      <div className="header">
        <div className="back neu" onClick={onBack} style={{ cursor: "pointer" }}>
          <BackIcon />
        </div>
        <div className="hlabel">MODULE &middot; CURRENT DIVIDER</div>
      </div>

      <div style={{ ...dPanelStyle, color: dCream, fontFamily: "Inter, Arial, sans-serif" }}>
        <p style={{ fontFamily: "monospace", fontSize: 10, letterSpacing: "0.14em", textTransform: "uppercase", color: dTeal, margin: "0 0 6px" }}>MOD.08</p>
        <h2 style={{ fontWeight: 800, fontSize: 20, margin: "0 0 4px", fontFamily: "'Baloo 2',sans-serif" }}>
          Current <span style={{ color: dGoldBright }}>Divider</span>
        </h2>
        <p style={{ color: dMuted, fontSize: 11.5, margin: "0 0 14px", lineHeight: 1.4 }}>
          Add any number of parallel branches and solve every branch current.
        </p>

        <p style={{ fontSize: 10.5, color: dMuted, margin: "0 0 6px" }}>Source type</p>
        <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
          <button style={dChip(mode === "voltage")} onClick={() => setMode("voltage")}>Voltage source</button>
          <button style={dChip(mode === "current")} onClick={() => setMode("current")}>Current source</button>
        </div>

        <p style={{ fontSize: 10.5, color: dMuted, margin: "0 0 6px" }}>{mode === "voltage" ? "Vs (volts)" : "I_T (amps)"}</p>
        <input type="number" step="any" value={source} onChange={(e) => setSource(e.target.value)} style={dInputStyle} />

        <p style={{ fontSize: 10.5, color: dMuted, margin: "14px 0 6px" }}>Parallel branches</p>
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {resistors.map((r, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <input
                type="number"
                step="any"
                value={r}
                onChange={(e) => updateRow(i, e.target.value)}
                placeholder={`R${i + 1} (Ω)`}
                style={{ ...dInputStyle, flex: 1 }}
              />
              <button
                onClick={() => removeRow(i)}
                disabled={resistors.length <= 2}
                style={{
                  width: 34, height: 34, flex: "none", borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center",
                  border: `1px solid ${dDanger}59`, background: dBg, color: dDanger, fontSize: 16, cursor: resistors.length <= 2 ? "default" : "pointer",
                  opacity: resistors.length <= 2 ? 0.25 : 1,
                }}
              >
                ×
              </button>
            </div>
          ))}
        </div>
        <button
          onClick={addRow}
          style={{ marginTop: 10, width: "100%", border: `1px dashed ${dGold}66`, borderRadius: 8, padding: "9px 0", background: "transparent", color: dGold, fontFamily: "monospace", fontSize: 11.5, cursor: "pointer" }}
        >
          + Add branch
        </button>

        {result.error && <div style={{ marginTop: 12, color: dDanger, fontSize: 12 }}>{result.error}</div>}
      </div>

      {!result.error && (
        <>
          <div style={dPanelStyle}>
            <p style={{ fontFamily: "monospace", fontSize: 10, color: dMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 8px" }}>{result.headlineLbl}</p>
            <div style={{ fontSize: 19, fontWeight: 700, color: dGoldBright }}>{result.headline}</div>
          </div>

          <div style={dPanelStyle}>
            <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 10px", fontFamily: "'Baloo 2',sans-serif" }}>Branch currents</h3>
            <div style={{ display: "grid", gridTemplateColumns: `repeat(${Math.min(result.Rs.length, 3)}, 1fr)`, gap: 10 }}>
              {result.Rs.map((r, i) => (
                <div key={i} style={{ textAlign: "center" }}>
                  <div style={{ fontFamily: "monospace", fontWeight: 700, fontSize: 14, color: dGoldBright }}>{cdFmtPlain(result.branches[i])} A</div>
                  <div style={{ fontFamily: "monospace", fontSize: 9, color: dMuted, marginTop: 4, textTransform: "uppercase" }}>I_R{i + 1} · {cdFmtPlain(r)}Ω</div>
                </div>
              ))}
            </div>
          </div>

          <div style={{ ...dPanelStyle, marginBottom: 26 }}>
            <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 10px", fontFamily: "'Baloo 2',sans-serif" }}>Steps</h3>
            {result.log.map((s, i) => (
              <div key={i} style={{ fontFamily: "monospace", fontSize: 11.5, padding: "3px 0", color: dCream }}>{s}</div>
            ))}
          </div>
        </>
      )}
      {result.error && <div style={{ height: 4 }} />}
    </div>
  );
}

/* =========================================================
   Resistor Code screen
   ========================================================= */
function ResistorScreen({ onBack }) {
  const [mode, setMode] = useState("forward"); // forward | reverse
  const [count, setCount] = useState(4);
  const [selections, setSelections] = useState(() => initSelections(4));
  const [target, setTarget] = useState("4700");

  function initSelections(c) {
    const slots = rccSlotDefs(c);
    let digitIdx = 0;
    return slots.map((slot) => {
      const val = rccDefaultFor(slot.type, slot.type === "digit" ? digitIdx++ : 0);
      return { type: slot.type, label: slot.label, value: val };
    });
  }

  const applyCount = (c) => {
    setCount(c);
    setSelections(initSelections(c));
  };

  const setSlot = (idx, value) => {
    setSelections((s) => s.map((sl, i) => (i === idx ? { ...sl, value: parseFloat(value) } : sl)));
  };

  const result = useMemo(() => {
    let digits, multEntry, tolEntry, tempcoEntry = null, baseValue;

    if (mode === "forward") {
      digits = [];
      selections.forEach((sl) => {
        const opts = rccOptionsFor(sl.type);
        const opt = opts.find((o) => o.value === sl.value);
        const color = opt ? opt.color : RCC_DIGITS[0];
        if (sl.type === "digit") digits.push({ v: sl.value, color });
        else if (sl.type === "mult") multEntry = { value: sl.value, name: color };
        else if (sl.type === "tol") tolEntry = { value: sl.value, name: color };
        else if (sl.type === "tempco") tempcoEntry = { value: sl.value, name: color };
      });
      if (!tolEntry) tolEntry = { value: 20, name: "None" };
      const num = digits.reduce((acc, d) => acc * 10 + d.v, 0);
      baseValue = num * multEntry.value;
    } else {
      const t = parseFloat(target);
      if (isNaN(t) || t <= 0) {
        return { err: "Enter a resistance greater than 0." };
      }
      const digitCount = count >= 5 ? 3 : 2;
      const best = rccNearestBands(t, digitCount);
      digits = best.digits.map((v) => ({ v, color: RCC_DIGITS[v] }));
      multEntry = { value: best.mult.value, name: best.mult.name };
      tolEntry = count >= 4 ? { value: RCC_DEFAULT_TOL, name: "Gold" } : { value: 20, name: "None" };
      if (count >= 6) tempcoEntry = { value: RCC_DEFAULT_TEMPCO, name: "Brown" };
      baseValue = best.value;
    }

    const tolLabel = tolEntry.name === "None" ? "±20% (unmarked)" : `±${tolEntry.value}%`;
    const steps = digits.map((d, i) => `Band ${i + 1}: ${d.color} → digit ${d.v}`);
    steps.push(`Band ${digits.length + 1}: ${multEntry.name} → ×${multEntry.value}`);
    if (tolEntry.name !== "None") steps.push(`Band ${digits.length + 2}: ${tolEntry.name} → ±${tolEntry.value}%`);
    if (tempcoEntry) steps.push(`Band ${digits.length + 3}: ${tempcoEntry.name} → ${tempcoEntry.value}ppm/K`);
    steps.push(`(${digits.map((d) => d.v).join("")}) × ${multEntry.value} = ${fmtR(baseValue)} Ω`);

    const visualColors = digits.map((d) => d.color).concat([multEntry.name]);
    if (tolEntry.name !== "None") visualColors.push(tolEntry.name);
    if (tempcoEntry) visualColors.push(tempcoEntry.name);

    return { baseValue, tolLabel, steps, visualColors, multIndex: digits.length };
  }, [mode, selections, target, count]);

  // dark "module" palette, distinct from the warm app theme on purpose —
  // this panel reads like a little instrument dropped into the app
  // accent follows the module's home-card color
  const rBg = "#181512", rPanel = "#211c17", rGold = "#5C88F0", rGoldBright = "#a5bef7";
  const rTeal = "#85a6f4", rCream = "#f4efe4", rMuted = "#a89f8f", rLine = "#3a3327", rDanger = "#e8735a";

  const rBtn = (active) => ({
    fontFamily: "monospace", fontSize: 11, borderRadius: 8, padding: "8px 6px", cursor: "pointer",
    border: `1px solid ${active ? rTeal : rGold + "40"}`,
    background: active ? rTeal + "1f" : rBg,
    color: active ? rTeal : rCream,
    textAlign: "center",
  });

  return (
    <div className="screen-body">
      <div className="header">
        <div className="back neu" onClick={onBack} style={{ cursor: "pointer" }}>
          <BackIcon />
        </div>
        <div className="hlabel">MODULE &middot; RESISTOR CODE</div>
      </div>

      <div style={{ margin: "14px 22px 0 22px", background: rPanel, color: rCream, fontFamily: "Inter, Arial, sans-serif", borderRadius: 20, padding: 18 }}>
        <p style={{ fontFamily: "monospace", fontSize: 10, letterSpacing: "0.14em", textTransform: "uppercase", color: rTeal, margin: "0 0 6px" }}>MOD.02</p>
        <h2 style={{ fontWeight: 800, fontSize: 20, margin: "0 0 4px", fontFamily: "'Baloo 2',sans-serif" }}>
          Resistor <span style={{ color: rGoldBright }}>Color Code</span>
        </h2>
        <p style={{ color: rMuted, fontSize: 11.5, margin: "0 0 18px", lineHeight: 1.4 }}>
          Pick colors to get the value, or enter a value to get the nearest bands. Works for 3–6 band resistors.
        </p>

        {/* visual band strip */}
        <div style={{ background: rBg, border: `1px solid ${rGold}29`, borderRadius: 14, padding: "18px 10px", marginBottom: 16 }}>
          {result.err ? (
            <div style={{ textAlign: "center", color: rDanger, fontSize: 12 }}>{result.err}</div>
          ) : (
            <>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "center", flexWrap: "wrap", gap: 5 }}>
                {result.visualColors.map((c, i) => (
                  <div
                    key={i}
                    style={{
                      width: 9, height: 30, flex: "none",
                      marginLeft: i === result.multIndex ? 12 : 0,
                      background: RCC_HEX[c] || "#888",
                      boxShadow: RCC_LIGHT.includes(c) ? "inset 0 0 0 1px rgba(0,0,0,0.25)" : "none",
                      borderRadius: 2,
                    }}
                  />
                ))}
              </div>
              <div style={{ display: "flex", justifyContent: "center", gap: 28, marginTop: 16 }}>
                <div style={{ textAlign: "center" }}>
                  <p style={{ fontSize: 9.5, color: rMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 3px" }}>Resistance</p>
                  <div style={{ fontWeight: 700, fontSize: 16, color: rGoldBright }}>{fmtR(result.baseValue)} Ω</div>
                </div>
                <div style={{ textAlign: "center" }}>
                  <p style={{ fontSize: 9.5, color: rMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 3px" }}>Tolerance</p>
                  <div style={{ fontWeight: 700, fontSize: 16, color: rTeal }}>{result.tolLabel}</div>
                </div>
              </div>
            </>
          )}
        </div>

        {/* mode */}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 14 }}>
          <button style={rBtn(mode === "forward")} onClick={() => setMode("forward")}>Bands → Value</button>
          <button style={rBtn(mode === "reverse")} onClick={() => setMode("reverse")}>Value → Bands</button>
        </div>

        {mode === "forward" && (
          <div style={{ marginBottom: 14 }}>
            <p style={{ fontSize: 10.5, color: rMuted, margin: "0 0 6px" }}>Resistor type</p>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 6 }}>
              {[3, 4, 5, 6].map((c) => (
                <button key={c} style={rBtn(count === c)} onClick={() => applyCount(c)}>{c} Band{c > 1 ? "s" : ""}</button>
              ))}
            </div>
          </div>
        )}

        {mode === "forward" ? (
          <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 4 }}>
            {selections.map((sl, i) => (
              <div key={i}>
                <label style={{ display: "block", fontSize: 10, color: rMuted, marginBottom: 4 }}>{sl.label}</label>
                <select
                  value={sl.value}
                  onChange={(e) => setSlot(i, e.target.value)}
                  style={{ width: "100%", background: rBg, border: `1px solid ${rGold}4d`, color: rCream, fontFamily: "monospace", fontSize: 12, padding: "8px 8px", borderRadius: 8, boxSizing: "border-box" }}
                >
                  {rccOptionsFor(sl.type).map((o) => (
                    <option key={o.value} value={o.value}>{o.text}</option>
                  ))}
                </select>
              </div>
            ))}
          </div>
        ) : (
          <div style={{ marginBottom: 4 }}>
            <label style={{ display: "block", fontSize: 10, color: rMuted, marginBottom: 4 }}>Resistance (Ω)</label>
            <input
              type="number"
              step="any"
              value={target}
              onChange={(e) => setTarget(e.target.value)}
              style={{ width: "100%", background: rBg, border: `1px solid ${rGold}4d`, color: rCream, fontFamily: "monospace", fontSize: 13, padding: "9px 11px", borderRadius: 8, boxSizing: "border-box" }}
            />
            <div style={{ marginTop: 10 }}>
              <span style={{ fontSize: 10, color: rMuted }}>Band count</span>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 6, marginTop: 6 }}>
                {[3, 4, 5, 6].map((c) => (
                  <button key={c} style={rBtn(count === c)} onClick={() => setCount(c)}>{c} Band{c > 1 ? "s" : ""}</button>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      <div style={{ margin: "14px 22px 0 22px", background: rPanel, color: rCream, borderRadius: 20, padding: 18 }}>
        <p style={{ fontFamily: "monospace", fontSize: 10, color: rMuted, textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 6px" }}>Resistance</p>
        <div style={{ fontSize: 19, fontWeight: 700, color: rGoldBright }}>
          {result.err ? "—" : `${fmtR(result.baseValue)} Ω ${result.tolLabel}`}
        </div>
        {!result.err && (
          <div style={{ color: rMuted, fontSize: 11, marginTop: 4 }}>{Math.round(result.baseValue).toLocaleString()} Ω exact</div>
        )}
      </div>

      <div style={{ margin: "14px 22px 0 22px", background: rPanel, color: rCream, borderRadius: 20, padding: 18 }}>
        <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 10px", fontFamily: "'Baloo 2',sans-serif" }}>Bands, left to right</h3>
        {result.err ? (
          <div style={{ color: rMuted, fontSize: 12 }}>—</div>
        ) : (
          result.steps.map((s, idx) => (
            <div key={idx} style={{ fontFamily: "monospace", fontSize: 11.5, padding: "3px 0" }}>{s}</div>
          ))
        )}
      </div>

      <div style={{ margin: "14px 22px 26px 22px", background: rPanel, color: rCream, borderRadius: 20, padding: 18 }}>
        <h3 style={{ fontWeight: 700, fontSize: 12.5, margin: "0 0 10px", fontFamily: "'Baloo 2',sans-serif" }}>Multiplier reference</h3>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 11.5 }}>
          <tbody>
            {[
              ["Black / Brown / Red", "×1 / ×10 / ×100"],
              ["Orange / Yellow / Green", "×1k / ×10k / ×100k"],
              ["Blue / Violet", "×1M / ×10M"],
              ["Gold / Silver", "×0.1 / ×0.01"],
            ].map(([name, formula]) => (
              <tr key={name} style={{ borderTop: `1px solid ${rLine}` }}>
                <td style={{ padding: "7px 4px", color: rGold, fontWeight: 600 }}>{name}</td>
                <td style={{ padding: "7px 4px", fontFamily: "monospace", color: rMuted }}>{formula}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* =========================================================
   Notepad screen
   ========================================================= */
function timeAgo(ts) {
  const diff = Date.now() - ts;
  const min = Math.floor(diff / 60000);
  if (min < 1) return "just now";
  if (min < 60) return min + "m ago";
  const hr = Math.floor(min / 60);
  if (hr < 24) return hr + "h ago";
  const d = Math.floor(hr / 24);
  return d + "d ago";
}

function NotepadScreen({ notes, setNotes, loaded }) {
  const [openId, setOpenId] = useState(null);
  const textareaRef = useRef(null);

  const openNote = (id) => setOpenId(id);
  useTick(30000);
  const closeNote = () => {
    const n = notes.find((x) => x.id === openId);
    if (n && !n.title.trim() && !n.body.trim()) {
      setNotes(notes.filter((x) => x.id !== n.id));
    }
    setOpenId(null);
  };

  const addNote = () => {
    const id = Date.now().toString();
    const note = { id, title: "", body: "", updatedAt: Date.now() };
    setNotes([note, ...notes]);
    setOpenId(id);
  };

  const updateNote = (id, patch) => {
    setNotes(notes.map((n) => (n.id === id ? { ...n, ...patch, updatedAt: Date.now() } : n)));
  };

  const deleteNote = (id) => {
    setNotes(notes.filter((n) => n.id !== id));
    if (openId === id) setOpenId(null);
  };

  const openNoteData = notes.find((n) => n.id === openId);

  useEffect(() => {
    if (openId && textareaRef.current) {
      textareaRef.current.focus();
    }
  }, [openId]);

  if (openNoteData) {
    return (
      <div className="screen-body">
        <div className="header">
          <div className="back neu" onClick={closeNote} style={{ cursor: "pointer" }}>
            <BackIcon />
          </div>
          <div className="hlabel">EDIT NOTE</div>
          <div
            className="back neu"
            onClick={() => deleteNote(openNoteData.id)}
            style={{ cursor: "pointer", marginLeft: "auto" }}
          >
            <TrashIcon />
          </div>
        </div>

        <div className="card note-editor neu">
          <input
            className="note-title-input"
            placeholder="Note title"
            value={openNoteData.title}
            onChange={(e) => updateNote(openNoteData.id, { title: e.target.value })}
          />
          <div className="note-divider" />
          <textarea
            ref={textareaRef}
            className="note-body-input"
            placeholder="Start writing..."
            value={openNoteData.body}
            onChange={(e) => updateNote(openNoteData.id, { body: e.target.value })}
          />
        </div>
        <div className="note-meta-footer">Saved &middot; {timeAgo(openNoteData.updatedAt)}</div>
      </div>
    );
  }

  return (
    <div className="screen-body">
      <div className="header">
        <div className="back neu" style={{ visibility: "hidden" }}>
          <BackIcon />
        </div>
        <div className="hlabel">STUDY &middot; NOTEPAD</div>
      </div>

      <div className="section-title" style={{ marginTop: 22 }}>
        {notes.length} {notes.length === 1 ? "note" : "notes"}
      </div>

      {notes.length === 0 ? (
        <div className="card empty-note neu">
          <div className="mod-ic" style={{ background: "rgba(43,38,32,0.06)", margin: "0 auto 10px auto" }}>
            <NotepadIcon />
          </div>
          <p>No notes yet. Tap the + button to jot down a formula, reminder, or idea.</p>
        </div>
      ) : (
        <div className="note-list">
          {notes.map((n) => (
            <div key={n.id} className="note-card neu" onClick={() => openNote(n.id)}>
              <div className="note-card-title">{n.title || "Untitled note"}</div>
              <div className="note-card-preview">{n.body ? n.body.slice(0, 80) : "No additional text"}</div>
              <div className="note-card-time">{timeAgo(n.updatedAt)}</div>
            </div>
          ))}
        </div>
      )}

      <button className="fab" onClick={addNote} aria-label="New note">
        <PlusIcon />
      </button>
    </div>
  );
}

/* =========================================================
   Bottom nav
   ========================================================= */
function BottomNav({ screen, setScreen }) {
  const items = [
    { id: "home", label: "Home", Icon: HomeIcon },
    { id: "notepad", label: "Notepad", Icon: NotepadIcon },
    { id: "profile", label: "Profile", Icon: ProfileIcon },
  ];
  return (
    <div className="navbar">
      <div className="navpill neu">
        {items.map((it) => (
          <div
            key={it.id}
            className={"navitem" + (screen === it.id ? " active" : "")}
            onClick={() => setScreen(it.id)}
            style={{ cursor: "pointer" }}
          >
            <it.Icon active={screen === it.id} />
          </div>
        ))}
      </div>
    </div>
  );
}

/* =========================================================
   Root app
   ========================================================= */
export default function CalligatorApp() {
  const [screen, setScreen] = useState("home");
  const [selectedAvatar, setSelectedAvatar] = useState(0);
  const [notes, setNotes] = useState([]);
  const [loaded, setLoaded] = useState(false);

  // load notes + avatar once from persistent storage
  useEffect(() => {
    (async () => {
      try {
        const raw = await store.get("notepad:notes");
        if (raw) {
          const parsed = JSON.parse(raw);
          if (Array.isArray(parsed)) setNotes(parsed);
        }
      } catch (e) {
        // no saved notes yet, start empty
      }
      try {
        const av = parseInt(await store.get("profile:avatar"), 10);
        if (av >= 0 && av < AVATAR_IMAGES.length) setSelectedAvatar(av);
      } catch (e) {
        // keep default avatar
      }
      setLoaded(true);
    })();
  }, []);

  // persist notes after the initial load
  useEffect(() => {
    if (!loaded) return;
    store.set("notepad:notes", JSON.stringify(notes)).catch((e) => console.error("Could not save notes", e));
  }, [notes, loaded]);

  // persist avatar choice
  useEffect(() => {
    if (!loaded) return;
    store.set("profile:avatar", String(selectedAvatar)).catch((e) => console.error("Could not save avatar", e));
  }, [selectedAvatar, loaded]);

  return (
    <div className="calligator-wrap">
      <style>{CSS}</style>
      <div className="screen">
        {screen === "home" && <HomeScreen onOpenModule={setScreen} />}
        {screen === "profile" && (
          <ProfileScreen selectedAvatar={selectedAvatar} setSelectedAvatar={setSelectedAvatar} onBack={() => setScreen("home")} />
        )}
        {screen === "notepad" && <NotepadScreen notes={notes} setNotes={setNotes} loaded={loaded} />}
        {screen === "resistor" && <ResistorScreen onBack={() => setScreen("home")} />}
        {screen === "ohm" && <OhmScreen onBack={() => setScreen("home")} />}
        {screen === "boolean" && <BooleanScreen onBack={() => setScreen("home")} />}
        {screen === "kmap" && <KMapScreen onBack={() => setScreen("home")} />}
        {screen === "seriesparallelr" && <SeriesParallelRScreen onBack={() => setScreen("home")} />}
        {screen === "vdivider" && <VoltageDividerScreen onBack={() => setScreen("home")} />}
        {screen === "lc" && <SeriesParallelLCScreen onBack={() => setScreen("home")} />}
        {screen === "cdiv" && <CurrentDividerScreen onBack={() => setScreen("home")} />}
        {![
          "resistor", "ohm", "boolean", "kmap", "seriesparallelr", "vdivider", "lc", "cdiv",
        ].includes(screen) && <BottomNav screen={screen} setScreen={setScreen} />}
      </div>
    </div>
  );
}

